class DoctorTax(models.Model):
    _name = 'doctor.tax'
    _rec_name = 'name'

    @api.model
    def _get_company(self):
        return self.env.company.id

    sync_type = sync.type
    sync_consol_id_unit = sync.consol_id_unit
    sync_consol_id_main = sync.consol_id_main
    sync_consol_date = sync.consol_date

    company_id = fields.Many2one('res.company',string="Company",required=True,default=_get_company)
    tax_type = fields.Selection([('pph21','PPH 21'), ('pph23','PPH 23')], string="Tax Type")
    tax_level = fields.Selection([('1','Tax Level-1'),('2','Tax Level-2'),('3','Tax Level-3'),('4','Tax Level-4'),('5','Tax Level-5'),('6','Tax Level-6')], string="Tax Tairing")
    tax_dpp_min = fields.Float(string="DPP Minimal")
    tax_dpp_max = fields.Float(string="DPP Maximal")
    tax_rate = fields.Float(string="Tax Rate")
    tax_rate2 = fields.Float(string="Tax Rate (Without NPWP)")
    name = fields.Char(string="Description")


        

    @api.model
    def get_view(self,view_id=None, view_type='form', **options):
        res = super(DoctorTax,self).get_view(view_id=view_id,view_type=view_type, **options)
        if view_type == 'form':
            res['arch'] = """
                    <form string="Doctor Tax Configuration">
                        <header>
                        </header>
                        <sheet>
                            <group>
                                <group>
                                    <field name="company_id" />
                                    <field name="tax_type"/>
                                    <field name="tax_level"/>
                                    <field name="name"/>
                                </group>
                                <group>
                                    <field name="tax_dpp_min"/>
                                    <field name="tax_dpp_max"/>
                                    <field name="tax_rate"/>
                                    <field name="tax_rate2"/>
                                </group>
                            </group>
                        </sheet>
                    </form>
            """
        elif view_type == 'tree':
            res['arch'] = """
                <tree string="Doctor Tax Configuration">
                    <field name="tax_type"/>
                    <field name="tax_level"/>
                    <field name="name"/>
                    <field name="tax_dpp_min"/>
                    <field name="tax_dpp_max"/>
                    <field name="tax_rate"/>
                    <field name="company_id"/>
                </tree>
            """
        elif view_type == 'search':
            res['arch'] = """
                <search string="Search Doctor Tax">
                    <filter string="PPH 21" domain="[('tax_type','=', 'pph21')]" help="PPH 21"/>
                    <filter string="PPh 23" domain="[('tax_type','=', 'pph23')]" help="PPH 23"/>
                    <separator/>
                    <field name="name"/>
                </search>
            """

        from lxml import etree
        doc = etree.XML(res['arch'])
        View = self.env['ir.ui.view'].sudo()
        res['arch'], res['fields'] = View.postprocess_and_fields(doc, self._name, validate=True)
        return res







class DoctorRate(models.Model):
    _name = 'doctor.rate'
    _rec_name = 'doctor_id'

    @api.model
    def _get_company(self):
        return self.env.company.id

    sync_type = sync.type
    sync_consol_id_unit = sync.consol_id_unit
    sync_consol_id_main = sync.consol_id_main
    sync_consol_date = sync.consol_date
    sync_is_arcus = sync.is_arcus

    company_id = fields.Many2one('res.company',string="Company",required=True,default=_get_company)
    doctor_id = fields.Many2one('account.analytic.account', string="Doctor", domain=[('sync_wipro_type','=','doctor_internal')])
    parent_id = fields.Many2one('doctor.rate', string="Parent")
    start_date_validity = fields.Date(string="Start Date Validity")
    end_date_validity = fields.Date(string="End Date Validity")
    guarantee_fee = fields.Float(string="Guarantee Fee")
    join_date = fields.Date(string="Join Date")
    join_prorate = fields.Boolean(string="Prorate GF")

    allowance = fields.Float(string="Allowance")
    is_npwp = fields.Boolean(string="Is NPWP")
    npwp = fields.Char(string="NPWP")
    npwp_name = fields.Char(string="Nama NPWP")
    email = fields.Char(string="Email", index=True, track_visibility='onchange')
    rate_line_ids = fields.One2many('doctor.rate.line','doctor_rate_id',string="Rate Line",copy=True)
    referal_line_ids = fields.One2many('doctor.rate.referal.line','doctor_rate_id',string="Rate Line",copy=True)
    bpjs_doctor_ids = fields.Many2many('account.analytic.account', relation='doctor_rate_analytic_bpjs_rel', string="Doctor BPJS Group (Odoo)", store=True, copy=False)
    rate_childs_ids = fields.One2many('doctor.rate', 'parent_id', string="Childs Doctor", copy=False)

