    is_tnc = fields.Boolean(string="Is TNC")

    is_hd_total = fields.Boolean(string="HD Parent")
    is_hd = fields.Boolean(string="Is HD")
    
    is_dental = fields.Boolean(string="Is Dental")
    is_grossup = fields.Boolean(string="Is Grossup")
    is_external = fields.Boolean(string="Is External")

