    last_release = fields.Datetime(string="Last Release Date", index=True, tracking=True)
    no_approval = fields.Boolean(string="No Approval?", index=True, tracking=True)
    active = fields.Boolean(string="Active", default=True, index=True, tracking=True)

    
    # @api.multi
    def action_draft(self):
        current = tools.datetime.strptime(tools.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),'%Y-%m-%d %H:%M:%S')
        for record in self:
            record.write({'state': 'draft'})
        return


    # @api.multi
    def action_ask_release(self):
        from datetime import timedelta
        current = tools.datetime.strptime(tools.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),'%Y-%m-%d %H:%M:%S')
        for record in self:
            record.write({'state': 'waiting'})


            record_name = record.doctor_id.display_name  # Or record.name if you have 'name' field
            base_url = self.env['ir.config_parameter'].sudo().get_param('web.base.url')
            record_link = '{}/web#id={}&model={}&view_type=form'.format(base_url, record.id, self._name)


            # Define this inside your method
            def extract_value(change, prefix):
                for suffix in ['char', 'text', 'float', 'integer', 'datetime']:
                    field_name = '{}_value_{}'.format(prefix, suffix)
                    value = getattr(change, field_name, False)
                    if value not in (False, None, ''):
                        return value
                return ''

            # Get all fields with tracking=True
            # tracked_fields = [
            #     field.name
            #     for field in self._fields.values()
            #     if getattr(field, 'track_visibility', None) == 'onchange'
            # ]

            # Tracked fields for header model
            header_tracked_fields = [
                field.name
                for field in self._fields.values()
                if getattr(field, 'track_visibility', None) == 'onchange'
            ]


            # Tracked fields for line model (use any record, assuming all lines use the same model)
            line_tracked_fields = []
            if record.rate_line_ids:
                line_model_obj = record.rate_line_ids[0]
                line_tracked_fields = [
                    field.name
                    for field in line_model_obj._fields.values()
                    if getattr(field, 'track_visibility', None) == 'onchange'
                ]




            # Get mail.messages in the last 3 days
            threshold_date = fields.Datetime.to_string(
                fields.Datetime.from_string(fields.Datetime.now()) - timedelta(days=3)
            )

            last_release_date = record.last_release

            messages = self.env['mail.message'].search([
                ('model', '=', self._name),
                ('res_id', '=', record.id),
                ('create_date', '>=', last_release_date),
            ])

            # Extract changes
            field_changes = []
            for msg in messages:
                for change in msg.tracking_value_ids:
                    if change.field in header_tracked_fields:
                        field_changes.append({
                            'date': fields.Datetime.from_string(msg.create_date).strftime('%Y-%m-%d %H:%M'),
                            'field': change.field_desc or change.field,
                            'old': extract_value(change, 'old'),
                            'new': extract_value(change, 'new')
                        })


                


            # Include mail.message from line_ids (e.g. record.line_ids)
            for line in record.rate_line_ids:
                
                if line.product_id:
                    line_name = "Line | {} - ( {} )".format(
                        line.service_id.display_name or '',
                        line.product_id.display_name or ''
                    )
                else:
                    line_name = ('Line | ' + str(line.service_id.display_name))

                # line_name = 'Line'
                line_model = line._name
                line_messages = self.env['mail.message'].search([
                    ('model', '=', line_model),
                    ('res_id', '=', line.id),
                    ('create_date', '>=', last_release_date),
                ])
                
                for msg in line_messages:
                    for change in msg.tracking_value_ids:
                        if change.field in line_tracked_fields:
                            field_changes.append({
                                'date': fields.Datetime.from_string(msg.create_date).strftime('%Y-%m-%d %H:%M'),
                                'field': "{}: {}".format(line_name, change.field_desc or change.field),
                                'old': extract_value(change, 'old'),
                                'new': extract_value(change, 'new')
                            })
                            


            # Build email body
            # if not field_changes:
            #     body_html = "<p>No tracked field changes in the last 3 days.</p>"
            # else:
            #     body_html = "<p><strong>Tracked Field Changes (last 3 days):</strong></p><ul>"

            body_html = """
                <p><strong>Record:</strong> {} has been changed<br/>
                <strong>Link:</strong> <a href="{}" target="_blank">Open in Odoo</a></p>
            """.format(record_name, record_link)

            if not field_changes:
                body_html += "<p>No tracked field changes.</p>"
            else:
                body_html += "<p><strong>Tracked Field Changes :</strong></p><ul>"




                for change in field_changes:
                    body_html += "<li><b>{}</b> on {}: <code>{}</code> --> <code>{}</code></li>".format(
                        change['field'], change['date'], change['old'], change['new']
                    )

                # for change in field_changes:
                #     if change['old'] == '' and change['new'] == '':
                #         continue  # skip empty changes

                #     body_html += "<li><b>{}</b> on {}: <code>{}</code> --> <code>{}</code></li>".format(
                #         change['field'], change['date'], change['old'], change['new']
                #     )

                # for change in field_changes:
                #     field = str(change.get('field', '')).strip()
                #     old = str(change.get('old', '')).strip()
                #     new = str(change.get('new', '')).strip()

                #     # Skip if field is empty or both old and new are empty
                #     if not field or (not old and not new):
                #         continue

                #     body_html += "<li><b>{}</b> on {}: <code>{}</code> --> <code>{}</code></li>".format(
                #         field, change['date'], old, new
                #     )

                body_html += "</ul>"


            # Get recipients (e.g. users with is_user_it = True)
            users = self.env['res.users'].search([('is_doctor_rate_approval', '=', True)])
            emails = [user.partner_id.email for user in users if user.partner_id.email]

            if not emails:
                raise UserError("No valid user partner emails found.")



            # Send email
            sender = 'odoo@mayapadahospital.com'

            self.env['mail.mail'].create({
                'subject': 'Field Change Notification',
                'body_html': body_html,
                # 'email_to': 'it.odoo@mayapadahospital.com',
                'email_to': ','.join(emails),
                'email_from': sender,
                'reply_to': sender,  # where replies go
            }).send()

        # return



    # @api.multi
    def approve(self):
        current = tools.datetime.strptime(
            tools.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
            '%Y-%m-%d %H:%M:%S'
        )

        for record in self:
            # If user is not IT and no_approval is not set, block approval
            if not self.env.user.is_doctor_rate_approval and not record.no_approval:
                raise ValidationError("You are not authorized to approve this action.")

            record.write({
                'state': 'release',
                'last_release': current
            })

        return

