class DoctorFeeWizard(models.TransientModel):
    _name = 'doctor.fee.wizard'

    @api.model
    def _get_company(self):
        return self.env.company.id

    def _year(orm):
        result = []
        year = 2019
        now = tools.datetime.now().year
        for loop in range(now - year):
            value = str(year + loop + 1)
            result += [(value, value)]
        return result

    company_id = fields.Many2one('res.company',string="Company",required=True,default=_get_company)
    # year = fields.Integer(string="Year Period", required=True)
    year = fields.Selection(_year, string="Year Period", required=True)
    month = fields.Selection([('1', 'January'), ('2', 'February'), ('3', 'March'),('4', 'April'), ('5', 'May'), ('6', 'June'),('7', 'July'), ('8', 'August'), ('9', 'September'),('10', 'October'), ('11', 'November'),('12', 'December')],string='Month Period',required=True)
    doctor_fee_ids = fields.Many2many('doctor.fee', relation='doctor_fee_compute_rel', string="Doctor for Compute", store=True)
    



    # @api.multi
    def create_doctor_fee(self):
        if self.doctor_fee_ids:
            for d in self.doctor_fee_ids:
                d.compute_bruto()
        else:
            doctor = self.env['doctor.fee'].search([('company_id', '=',self.company_id.id),('year', '=', self.year),('month', '=', self.month),('state', '=', 'draft')])
            # if not doctor:
            self.env.cr.execute("""
                SELECT distinct 
                    a.doctor_id, 
                    a.is_pot_gp, 
                    a.is_pot_total, 
                    a.is_dental,
                    a.is_external,
                    a.is_grossup,
                    a.is_npwp,
                    a.npwp,
                    a.guarantee_fee
                FROM doctor_rate a
                WHERE a.company_id = '%s' 
                    AND a.doctor_id not in (
                        select t.doctor_id 
                        from doctor_fee t
                        where t.company_id = a.company_id
                            and t.year = '%s'
                            and t.month = '%s' ) 
            """ % (self.company_id.id, self.year, self.month))

            lines = self.env.cr.dictfetchall()
            if lines:
                for line in lines:
                    self.env['doctor.fee'].create({
                        'doctor_id':int(line['doctor_id']),
                        'is_pot_gp':line['is_pot_gp'],
                        'is_pot_total':line['is_pot_total'],
                        'is_dental':line['is_dental'],
                        'is_grossup':line['is_grossup'],
                        'is_external':line['is_external'],
                        'is_npwp':line['is_npwp'],
                        'gf': line['guarantee_fee'],
                        'npwp':line['npwp'],
                        'company_id':self.company_id.id,
                        'year':self.year,
                        'month':self.month
                    })
                return
            for d in doctor:
                d.compute_bruto()




