class PayoutWizard(models.TransientModel):
    _name = 'payout.wizard'
    
    @api.model
    def _get_company(self):
        return self.env.company.id

    company_id = fields.Many2one('res.company',string="Company",required=True,default=_get_company)
    start_date = fields.Date(string="Start Date", required=True)
    end_date = fields.Date(string="End Date", required=True)
    reference_no = fields.Char(string="Reference", required=True)
    billno = fields.Char(string="Specific Bill No.", required=True, default="%%%%")
    admission_no = fields.Char(string="Specific Admission No.", required=True, default="%%%%")

    # @api.multi
    def generate(self,reference_no=reference_no,start_date=start_date,end_date=end_date,company_id=company_id,billno=billno, admission_no=admission_no):
        for record in self:
            reference_no = record.reference_no
            billno = record.billno
            admission_no = record.admission_no
            start_date = record.start_date
            end_date = record.end_date
            company_id = record.company_id.id
            payout = record.env['doctor.payout.line']
            # already = payout.search([('tglproses', '>=', self.start_date),('tglproses', '>=', self.end_date)])
            # if already:
            #     raise exceptions.ValidationError('Billing periode tersebut masih ada di worklist payout interface!')
