    # @api.multi
    def _sync_doctor_fee_other_detail(self, sync_type):
        import trollius as asyncio
        sync_ids ={} # {int(record.sync_id): int(record.id) for record in self.sudo().search([('sync_type', '=',sync_type), ('sync_id', '>',0)])}
        sync_date = self.sudo().search([('sync_type', '=', sync_type)], order='sync_date desc', limit=1).sync_date
        data = []
        date = '' + (tools.datetime.now() + tools.timedelta(hours=7) - tools.timedelta(days=1)).strftime('%Y-%m-%d')
        year = (int(tools.datetime.now().strftime('%Y')))
        month = (int(tools.datetime.now().strftime('%m')) - 1)
        day = (int(tools.datetime.now().strftime('%d')))
        # year = 2021
        # month = 3
        # day = 15
        print (year) 
        print (month) 
        print (day)
        
        if day == 15:
            query = """
                SELECT 
                    -- a.sync_type,
                    -- a.TglProses
                    a.FeeType fee_type,
                    a.ReferenceNo reference_no,
                    a.DoctorID doctor_id,
                    a.DoctorCode doctor_code,
                    a.DoctorName doctor_name,
                    a.PrimaryDocID primary_id,
                    a.PrimaryDocCode primary_code,
                    a.PrimaryDocName primary_name,
                    a.AdmissionID admission_id,
                    a.AdmissionNumber admission_no,
                    a.AdmitDate admit_date,
                    a.PatientType patient_type,
                    a.BillID bill_id,
                    a.BillNo bill_no,
                    a.BillDate bill_date,
                    a.ServiceName service_name,
                    a.ServiceItemName service_item_name,
                    a.DepartmentName department_name,
                    a.BillAmount total,
                    a.FeeAmount rate,
                    a.PatientID patient_id,
                    a.RegCode patient_regcode,
                    a.PatientName patient_name,
                    a.PayerID payer_id,
                    a.PayerName payer_name,
                    a.PayerCode payer_code,
                    a.PayerType payer_type,
                    a.Tahun 'year',
                    a.Bulan 'month',
                    'confirmed' state
                FROM dbo.VRP_OdooGetFeeDoctors a 
                WHERE a.Tahun = '%s'
                    AND a.Bulan = '%s'
                    AND a.Hari = '%s'
                """ % (year, month, day)
            # raise exceptions.ValidationError(query)
            print (query)
            data += sync.get_data(sync.servers.get(sync_type), query)
            print (data)
            if not data:
                print ("No data available")
                return
            fields_without_id = tuple(
                key for key in self._fields
                if key != 'id' and 'property' not in key and 'ids' not in key
                and self._fields[key].required == True
                and self._fields[key].store == True)
            columns = tuple(key for key in data[0].keys() if key in self._fields and key not in fields_without_id) + ('sync_date', 'sync_type') if data else ()
            fields_without_id += columns
            columns += tuple(key for key in data[0].keys() if key in self._fields and key not in columns) if data else ()
            fields = fields_without_id + ('id', )
            if columns:
                columns += ('id', )
            default_values = {}
            for field in fields:
                if field in columns:
                    continue
                default = self._fields[field].default
                if callable(default):
                    default = default(self)
                if isinstance(default, models.Model):
                    default = default.id
                default_values[field] = default
            values = ''
            now = tools.datetime.now().strftime('%Y-%m-%d %H:%M:%S')

            @asyncio.coroutine
            def process_query(object):
                for value in default_values:
                    object[value] = default_values[value]

                object['id'] = 'DEFAULT'
                object['sync_date'] = now
                object['sync_type'] = sync_type
                object['company_id'] = self.env['res.company'].sudo().search([('sync_type', '=', sync_type)], limit=1).id
                value = False
                for field in fields:
                    if value:
                        value += ', '
                    else:
                        value = '('
                    if field == 'id' and object['id'] == 'DEFAULT':
                        value += object['id']
                        continue
                    if type(object[field]) in [str, unicode]:
                        string = object[field]
                        value += "'" + string.replace("'", "''") + "'"
                        continue
                    value += sync.json(object[field])
                value += ')'
                return value
                #values += value

            loop = asyncio.get_event_loop()
            tasks = [asyncio.coroutine(process_query(object)) for object in data]
            for result in loop.run_until_complete(asyncio.gather(*tasks)):
                if result:
                    if values:
                        values += ', '
                    values += result
            excluded = sync.remove_unicode(str(tuple('EXCLUDED.' + field for field in fields_without_id))).replace("'", "")
            columns = sync.remove_unicode(str(fields)).replace("'", "")
            columns_without_id = sync.remove_unicode(str(fields_without_id)).replace("'", "")
            try:
                print (values)
            except UnicodeEncodeError:
                print (values.encode('ascii', 'ignore').decode('ascii'))
            if not values:
                print ("No data available")
                return
            query = "INSERT into doctor_fee_others_detail %s values %s on conflict (id) do update set %s = %s" % (columns, values, columns_without_id, excluded)
            print (query.encode('utf8'))
            self.env.cr.execute(query)

            
            # update patient_group
            query = """
                UPDATE doctor_fee_others_detail AS a 
                SET patient_group = (CASE a.patient_type 
                    WHEN '2' THEN 'InPatient'
                    WHEN '3' THEN 'Emergency'
                    ELSE 'OutPatient' END) 
                WHERE a.patient_group IS NULL
                """
            print (query)
            self.env.cr.execute(query)

            # update company_id
