class DoctorServiceCostWizard(models.TransientModel):
    _name = 'doctor.service.cost.wizard'

    @api.model
    def _get_company(self):
        return self.env.company.id

    company_id = fields.Many2one('res.company',string="Company",required=True,default=_get_company)
    start_date = fields.Date(string="Start Date", required=True)
    end_date = fields.Date(string="End Date", required=True)
    # year = fields.Integer(string="Year Period", required=True)
    # month = fields.Selection([(1, 'January'), (2, 'February'), (3, 'March'),(4, 'April'), (5, 'May'), (6, 'June'),(7, 'July'), (8, 'August'), (9, 'September'),(10, 'October'), (11, 'November'),(12, 'December')],string='Month Period',required=True)

    @api.model
    def get_view(self,view_id=None, view_type='form', **options):
        res = super(DoctorServiceCostWizard,self).get_view(view_id=view_id,view_type=view_type, **options)
        if view_type == 'form':
            res['arch'] = """
                <form string="Report Fee Doctor Service Cost">
                    <group>
                        <field name="company_id" />
                        <field name="start_date" />
                        <field name="end_date" />
                    </group>
                    <footer>
                        <button name="sync_service_cost" string="Sync" type="object" class="oe_highlight"/>
                    </footer>
                </form>
            """
        from lxml import etree
        doc = etree.XML(res['arch'])
        View = self.env['ir.ui.view'].sudo()
        res['arch'], res['fields'] = View.postprocess_and_fields(doc, self._name, validate=True)
        return res
    
    def sync_service_cost(self):

        # cleansung data
        query = """
            UPDATE sale_order_line
            SET service_cost_unit = NULL,
                service_cost_total = NULL
            WHERE company_id = {company_id}
                AND tglproses BETWEEN '{start_date}' AND '{end_date}'
            """.format(company_id=self.company_id.id,
                       start_date=self.start_date,
                       end_date=self.end_date)
        
        open('/opt/odoo16/logs/doctor_fee_bulk_update.log', 'a+').write('\n' + str(tools.datetime.now()) + ' Query \n' + str(query))
        self.env.cr.execute(query)

        if self.company_id.sync_type in ('1','2'):
            # update sale_order_line wipro
            query = """
                UPDATE sale_order_line AS sol
                SET
                    service_cost_unit = subquery.total_service_cost,
                    service_cost_total = subquery.total_service_cost
                FROM (
                    SELECT
                        dfl.order_no,
                        sol.type_line,
                        dfl.odoo_admission_id,
                        dfl.bill_no,
                        dfl.odoo_service_id,
                        dfl.odoo_service_item_id,
                        SUM(dfl.rate) AS total_service_cost
                    FROM
                        doctor_fee_line AS dfl
                    INNER JOIN sale_order_line AS sol ON dfl.odoo_admission_id = sol.order_id
                        AND dfl.bill_no = sol.billno
                        AND dfl.odoo_service_id = sol.service_categ_id
                        AND dfl.odoo_service_item_id = sol.product_id
                        AND dfl.order_no = sol.order_no
                    WHERE
                        dfl.company_id = {company_id}
                        AND dfl.state = 'confirmed'
                        AND sol.tglproses BETWEEN '{start_date}' AND '{end_date}'
                        AND sol.type_line IN ('BILL', 'BILL CANCEL')
                    GROUP BY
                        dfl.order_no,
                        sol.type_line,
                        dfl.odoo_admission_id,
                        dfl.bill_no,
                        dfl.odoo_service_id,
                        dfl.odoo_service_item_id
                ) AS subquery
                WHERE
                    sol.order_no = subquery.order_no
                    AND sol.type_line = subquery.type_line
                    AND sol.order_id = subquery.odoo_admission_id
                    AND sol.billno = subquery.bill_no
                    AND sol.service_categ_id = subquery.odoo_service_id
                    AND sol.product_id = subquery.odoo_service_item_id;
                """.format(company_id=self.company_id.id,
                        start_date=self.start_date,
                        end_date=self.end_date)
            
            open('/opt/odoo16/logs/doctor_fee_bulk_update.log', 'a+').write('\n' + str(tools.datetime.now()) + ' Query \n' + str(query))
            self.env.cr.execute(query)


            # khusus MHTG
            if self.company_id.sync_type in ['2']:
                # update sale_order_line wipro khusus investigasi
                query = """	
                    --update investigation  
                    UPDATE sale_order_line AS sol SET
                        service_cost_unit = subquery.total_service_cost,
                        service_cost_total = subquery.total_service_cost
                    FROM (
                        SELECT
                            dfl.order_no,
                            sol.type_line,
                            dfl.odoo_admission_id,
                            dfl.bill_no,
                            dfl.odoo_service_id,
                            dfl.odoo_service_item_id,
                            SUM(dfl.rate) AS total_service_cost
                        FROM doctor_fee_line AS dfl
                        INNER JOIN sale_order_line AS sol 
                        ON sol.order_id = dfl.odoo_admission_id 
                            AND dfl.bill_no = sol.billno
                            AND dfl.odoo_service_id = sol.service_categ_id
                            AND dfl.odoo_service_item_id = sol.product_id
                            --AND dfl.order_no = sol.order_no
                        LEFT JOIN product_category AS pc ON pc.id  = sol.service_categ_id 
                        WHERE dfl.company_id = {company_id}
                            AND dfl.state in ('confirmed','posted')
                            AND sol.tglproses >= '{start_date}' 
                            AND sol.tglproses <= '{end_date}'
                            AND sol.type_line IN ('BILL', 'BILLING')
                            AND pc.name ilike '%Investigation%'
                        GROUP BY	
                            dfl.order_no,
                            sol.type_line,
                            dfl.odoo_admission_id,
                            dfl.bill_no,
                            dfl.odoo_service_id,
                            dfl.odoo_service_item_id
                    ) AS subquery
                    WHERE sol.type_line = subquery.type_line
                        AND sol.order_id = subquery.odoo_admission_id
                        AND sol.billno = subquery.bill_no
                        AND sol.service_categ_id = subquery.odoo_service_id
                        AND sol.product_id = subquery.odoo_service_item_id
                    """.format(company_id=self.company_id.id,
                            start_date=self.start_date,
                            end_date=self.end_date)
                
                open('/opt/odoo16/logs/doctor_fee_bulk_update.log', 'a+').write('\n' + str(tools.datetime.now()) + ' Query \n' + str(query))
                self.env.cr.execute(query)


            # khusus MHJS
            if self.company_id.sync_type in ['1']:
                # update sale_order_line wipro khusus surgeon fee/anesthetis fee
                query = """	
                    --update surgeon/anestesi fee  
                    UPDATE sale_order_line AS sol SET
                        service_cost_unit = 0.8 * sol.price_total,
                        service_cost_total =  0.8 * sol.price_total
                    FROM product_category pc
                    WHERE pc.id = sol.service_categ_id 
                        AND pc.name in('Anestesist Fee','Anesthetist Fee','Asst Surgeon Fee','Surgeon Fee')
                        AND sol.company_id = {company_id}
                        AND sol.tglproses >= '{start_date}' 
                        AND sol.tglproses <= '{end_date}'
                        AND sol.type_line IN ('BILL', 'BILLING')
                    """.format(company_id=self.company_id.id,
                            start_date=self.start_date,
                            end_date=self.end_date)
                
                open('/opt/odoo16/logs/doctor_fee_bulk_update.log', 'a+').write('\n' + str(tools.datetime.now()) + ' Query \n' + str(query))
                self.env.cr.execute(query)

        else:
            # update sale_order_line dhealth
            query = """
                UPDATE sale_order_line AS sol
	            SET
	                service_cost_unit = subquery.total_service_cost,
	                service_cost_total = subquery.total_service_cost
	            FROM (
					SELECT
                        sol.id,
                        SUM(dfl.rate) AS total_service_cost
                    FROM
                        doctor_fee_line AS dfl
                    INNER JOIN doctor_payout_line dpl on dfl.payout_id=dpl.id
                    INNER JOIN sale_order_line AS sol ON dpl.line_id = sol.id
                    WHERE
                        dfl.company_id = {company_id}
                        AND dfl.state = 'confirmed'
                        AND sol.tglproses BETWEEN '{start_date}' AND '{end_date}'
                        AND sol.type_line IN ('BILLING', 'BILLING CANCEL')
                    GROUP BY sol.id
                ) AS subquery
               	WHERE sol.id = subquery.id;
                """.format(company_id=self.company_id.id,
                        start_date=self.start_date,
                        end_date=self.end_date)
            
            open('/opt/odoo16/logs/doctor_fee_bulk_update.log', 'a+').write('\n' + str(tools.datetime.now()) + ' Query \n' + str(query))
            self.env.cr.execute(query)
            

