    @api.model
    def _sync_doctor_mcu_manual(self, sync_type='1', date=False):
        import trollius as asyncio
        sync_ids = {int(record.sync_id): int(record.id) for record in self.sudo().search([('sync_type', '=',sync_type), ('sync_id', '>',0)])}
        sync_date = self.sudo().search([('sync_type', '=', sync_type)],order='sync_date desc',limit=1).sync_date
        data = []
        # date = '' + (tools.datetime.now() + tools.timedelta(hours=7) - tools.timedelta(days=1)).strftime('%Y-%m-%d')
        # date = '2020-02-10'
        query = """
            SELECT 
                sync_id,
                company_id,
                TglProses tglproses,
                PatientType patient_type,
                PatientGroup patient_group,
                BillNo title,
                BillNo name,
                BillID bill_id,
                BillNo bill_no,
                BillDate bill_date,
                AdmissionID admission_id,
                AdmissionNumber admission_no,
                AdmitDate admit_date,
                PatientID patient_id,
                RegCode patient_regcode,
                PatientName patient_name,
                PackageID package_id,
                PackageName package_name,
                DoctorID primary_id,
                DoctorCode primary_code,
                DoctorName primary_name,
                PayerID payer_id,
                PayerCode payer_code,
                PayerName payer_name,
                PayerType payer_type,
                0 total,
                is_updated
            FROM dbo.VRP_OdooFeeDoctor_MCUHeader a 
            WHERE a.tglproses = '%s'
            """ % (date)
        print (query)
        data += sync.get_data(sync.servers.get(sync_type), query)
        print (data)
        if not data:
            print ("No data available")
            return
        fields_without_id = tuple(
            key for key in self._fields
            if key != 'id' and 'property' not in key and 'ids' not in key
            and self._fields[key].required == True
            and self._fields[key].store == True)
        columns = tuple(
            key for key in data[0].keys()
            if key in self._fields and key not in fields_without_id) + ('sync_date', 'sync_type') if data else ()
        fields_without_id += columns
        columns += tuple(
            key for key in data[0].keys()
            if key in self._fields and key not in columns) if data else ()
        fields = fields_without_id + ('id', )
        if columns:
            columns += ('id', )
        default_values = {}
        for field in fields:
            if field in columns:
                continue
            default = self._fields[field].default
            if callable(default):
                default = default(self)
            if isinstance(default, models.Model):
                default = default.id
            default_values[field] = default
        values = ''
        now = tools.datetime.now().strftime('%Y-%m-%d %H:%M:%S')

        @asyncio.coroutine
        def process_query(object):
            for value in default_values:
                object[value] = default_values[value]

            object['id'] = 'DEFAULT'
            object['sync_date'] = now
            object['sync_type'] = sync_type
            object['company_id'] = self.env['res.company'].sudo().search([('sync_type', '=', sync_type)], limit=1).id
            value = False
            for field in fields:
                if value:
                    value += ', '
                else:
                    value = '('
                if field == 'id' and object['id'] == 'DEFAULT':
                    value += object['id']
                    continue
                if type(object[field]) in [str, unicode]:
                    string = object[field]
                    value += "'" + string.replace("'", "''") + "'"
                    continue
                value += sync.json(object[field])
            value += ')'
            return value
            #values += value

        loop = asyncio.get_event_loop()
        tasks = [asyncio.coroutine(process_query(object)) for object in data]
        for result in loop.run_until_complete(asyncio.gather(*tasks)):
            if result:
                if values:
                    values += ', '
                values += result
        excluded = sync.remove_unicode(str(tuple('EXCLUDED.' + field for field in fields_without_id))).replace("'", "")
        columns = sync.remove_unicode(str(fields)).replace("'", "")
        columns_without_id = sync.remove_unicode(str(fields_without_id)).replace("'", "")
        try:
            print (values)
        except UnicodeEncodeError:
            print (values.encode('ascii', 'ignore').decode('ascii'))
        if not values:
            print ("No data available")
            return
        query = "INSERT into doctor_mcu %s values %s on conflict (id) do update set %s = %s" % (columns, values, columns_without_id, excluded)
        print (query.encode('utf8'))
        self.env.cr.execute(query)

        # update sale.order object
        query = """
            UPDATE doctor_mcu AS a SET
                odoo_admission_id = b.id
            FROM sale_order b 
            WHERE b.sync_id=a.admission_id
                and b.sync_type=a.sync_type
                and a.odoo_admission_id IS NULL
            """
        print (query)
        self.env.cr.execute(query)

        # update patient object
        query = """
            UPDATE doctor_mcu AS a SET
                odoo_patient_id = b.id
            FROM res_partner b 
            WHERE b.sync_id=a.patient_id
                and b.sync_type=a.sync_type
                and b.patient=true
                and b.active=true
                and a.odoo_patient_id IS NULL
            """
        print (query)
        self.env.cr.execute(query)

        # update payer object
        query = """
            UPDATE doctor_mcu AS a SET
                odoo_payer_id = b.id
            FROM res_partner b 
            WHERE b.sync_id=a.payer_id
                and b.sync_type=a.sync_type
                and b.insurance=true
                and b.active=true
                and a.odoo_payer_id IS NULL
            """
        print (query)
        self.env.cr.execute(query)

        # update payer private
        query = """
            UPDATE doctor_mcu AS a SET
                odoo_payer_id = 5817
            WHERE a.odoo_payer_id IS NULL
                and a.payer_name='PRIVATE'
            """
        print (query)
        self.env.cr.execute(query)

        # update package object
        query = """
            UPDATE doctor_mcu AS a SET
                odoo_package_id = c.id
            FROM product_template b
            INNER JOIN product_product c ON c.product_tmpl_id=b.id
            WHERE b.sync_id=a.package_id
                and b.sync_type=a.sync_type
                and b.active=true
                and a.odoo_package_id IS NULL
            """
        print (query)
        self.env.cr.execute(query)

        # update doctor
        query = """
            UPDATE doctor_mcu AS a SET
                odoo_primary_id = c.id
            FROM res_partner b
            INNER JOIN account_analytic_account c 
            ON c.partner_id=b.id 
                and c.sync_wipro_type='doctor_internal'
            WHERE b.sync_id=a.primary_id
                and b.sync_type=a.sync_type
                and b.doctor=true
                and b.active=true
                and a.odoo_primary_id IS NULL
            """
        print (query)
        self.env.cr.execute(query)




