class SendEmailWizard(models.TransientModel):
    _name = 'send.email.wizard'

    doctor_fee_id = fields.Many2one('doctor.fee', string="Doctor Fee", required=True)
    actual_date = fields.Date(string="Actual Date", required=True)
    payment_type = fields.Selection([('cash', 'Cash'), ('transfer', 'Bank Transfer')],string='Payment Type', required=True)


    # @api.multi
    def action_send_email(self):
        # self.ensure_one()
        record = self.doctor_fee_id
        if record.company_id.company_code == 'MHBG':
            pdf_base64 = record._get_file_src_mhbg(record.id, ext='pdf')
        elif record.company_id.company_code == 'MHTG':
            pdf_base64 = record._get_file_src_mhtg(record.id, ext='pdf')
        elif record.company_id.company_code == 'MHJS':
            pdf_base64 = record._get_file_src_arcus(record.id, ext='pdf')
        else:
            pdf_base64 = record._get_file_src(record.id, ext='pdf')

        if isinstance(pdf_base64, list) and len(pdf_base64) > 0:
            pdf_base64 = pdf_base64[0]

        if not pdf_base64:
            raise UserError("PDF tidak ada")

        header_template = record.env['ir.config_parameter'].sudo().get_param('doctor_fee.email_header')
        body_template = record.env['ir.config_parameter'].sudo().get_param('doctor_fee.email_body')

        values_header = {
            'doctor_name': (record.doctor_id.name or '').upper(),
            'month': datetime.datetime(2000, int(record.month), 1).strftime('%B') or '',
            'year': record.year or ''
        }

        values_body = {
            'doctor_name': record.doctor_id.name or '',
            'month': datetime.datetime(2000, int(record.month), 1).strftime('%B') or '',
            'year': record.year or '',
            'nominal': "{:,.0f}".format(record.thp or 0).replace(',', '.'),
            'actual_date': self.actual_date or '',
            'company': record.company_id.name or '',
            'payment_type': self.payment_type or ''
        }

        header_html = header_template.format(**values_header)
        body_html = body_template.format(**values_body)

        # Cek apakah attachment sudah ada
        existing_attachment = record.env['ir.attachment'].search([
            ('name', '=', header_html + '.pdf'),
            ('res_model', '=', record._name),
            ('res_id', '=', record.id),
        ], limit=1)

        if existing_attachment:
            # Update attachment yang sudah ada
            existing_attachment.write({
                'datas': pdf_base64,
            })
            attachment = existing_attachment
        else:
            # Buat baru kalau belum ada
            attachment = record.env['ir.attachment'].create({
                'name': header_html + '.pdf',
                'datas': header_html + '.pdf',
                'type': 'binary',
                'datas': pdf_base64,
                'res_model': record._name,
                'res_id': record.id,
                'mimetype': 'application/pdf',
            })

        # Ambil semua attachment yang sudah di-upload di record doctor.fee (logo.png, dll)
        existing_attachments = self.env['ir.attachment'].search([
            ('res_model', '=', 'doctor.fee'),
            ('res_id', '=', record.id),
            ('id', '!=', attachment.id),  # exclude PDF yang baru dibuat
        ])

        # Gabungkan: PDF generated + attachment existing dari record
        all_attachment_ids = [(4, attachment.id)]
        for att in existing_attachments:
            all_attachment_ids.append((4, att.id))
            
        # get address email    
        email_to = record.env['doctor.rate'].search([('doctor_id', '=', record.doctor_id.id)], limit=1).email
        if email_to == False:
            raise exceptions.ValidationError(_(str("Alamat Email Doctor Tidak Ditemukan")))

        # kirim email
        mail = record.env['mail.mail'].create({
            'subject': header_html,
            'body_html': body_html,
            'email_to': email_to,
            'email_from': 'odoo@mayapadahospital.com',
            'attachment_ids': all_attachment_ids,
        })

        try:
            mail.send()
            record.email_send = True
        except Exception as e:
            record.email_send = False
            _logger.error("Gagal mengirim email: %s", str(e))
    

    @api.model
    def get_view(self,view_id=None, view_type='form', **options):
        res = super(SendEmailWizard,self).get_view(view_id=view_id,view_type=view_type, **options)  
        if view_type == 'form':
            res['arch'] = """
                <form string="Send Email">
                    <group>
                        <field name="doctor_fee_id" invisible="1"/>
                        <field name="actual_date"/>
                        <field name="payment_type"/>
                    </group>
                    <footer>
                        <button name="action_send_email" type="object" string="Send Email" class="oe_highlight"/>
                        <button special="cancel" string="Cancel"/>
                    </footer>
                </form>
            """
        from lxml import etree
        doc = etree.XML(res['arch'])
        View = self.env['ir.ui.view'].sudo()
        res['arch'], res['fields'] = View.postprocess_and_fields(doc, self._name, validate=True)
        return res


