    # @api.multi
    def unlink(self):
        for r in self:
            if r.state in ['confirmed','posted']:
                raise UserError("You Can't Delete Doctor Fee State in Confirmed and Posted.")
        return super(DoctorFee, self).unlink()
    

    def _compute_transaction_ids(self):
        for record in self:
            if record.transaction_line_ids:
                record.transaction_ids = record.transaction_line_ids.filtered(lambda x: x.is_bpjs is not True)
            else:
                record.transaction_ids = False
                
    def _compute_accrual_ids(self):
        for record in self:
            if record.transaction_line_ids:
                record.accrual_ids = record.transaction_line_ids.filtered(lambda x: x.is_bpjs is True)
            else:
                record.accrual_ids = False


    # @api.multi
    def button_print_tnc(self):
        return {
            'name': _('Button Print TNC'),
            'type': 'ir.actions.act_window',
            'view_type': 'form',
            'view_mode': 'form',
            'view_id': False,
            'res_model': 'doctor.fee.tnc.wizard',
            'target': 'new',
            'context': {'default_year': self.year,
                        'default_month': self.month,
                        'default_doctor_fee_id': self.id,
                        },
            } 
                

    @api.onchange('doctor_id', 'doctor_id.company_id')
    def onchange_company(self):
        for record in self:
            record.company_id = record.doctor_id.company_id.id

    @api.depends('other_transaction_ids.amount')
    def _compute_other(self):
        for record in self:
            record.other = 0
            record.gf_other = 0
            for line in record.other_transaction_ids:
                if line.credit_gf:
                    record.gf_other += line.amount
                else:
                    record.other += line.amount

    @api.depends('deduction_transaction_ids.amount')
    def _compute_deduction(self):
        for record in self:
            record.deduction = 0
            for line in record.deduction_transaction_ids:
                record.deduction += line.amount
            record.deduction *= -1

    # @api.multi
    def compute_line(self):
        for record in self:
            if record.transaction_line_ids:
                for line in record.transaction_line_ids:
                    line._compute_fee_line()


    # @api.multi
    def compute_grossup(self,bruto=0,bruto_prev=0,pph21_prev=0,grossup_prev=0):
        tax_level1 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',1)], limit=1)
        tax_level2 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',2)], limit=1)
        tax_level3 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',3)], limit=1)
        tax_level4 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',4)], limit=1)
        tax_level5 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',5)], limit=1)
        
        bruto_total = bruto + bruto_prev
        bruto_total_50 = bruto_total / 2
        grossup_total = 0
        grossup = 0
        grossup_selisih = 0
        grossup_tambahan = 0
        grossup_rate = 0
        pph21_total = 0
        pph21 = 0
        pph21_rate = 0
        pph21_lapis_1 = pph21_lapis_2 = pph21_lapis_3 = pph21_lapis_4 = pph21_lapis_5 = 0

        # konsep sederhana perhitung grossup double teiring progressive
        # grossup nilai PPH berdasarkan rate teiring
        # jika masih ada selisih di PPH, maka nilai selisih perlu di grossup lagi dengan rate yang sama

        # Tunjangan PPH = grossup
        # Total Bruto = 110.000.000 + grossup
        # DPP 50% = 50% x (110.000.000 + grossup)
        # DPP 50% = 55.000.000 +  0.5 grossup

        # (5% x 50.000.000 ) + ( 15% x ( 5.000.000 + 0.5 grossup )) = grossup
        # 2.500.000 + 750.000 + 7.5% grossup = grossup
        # 3.250.000 = grossup - 7.5% grossup
        # 92.5% grossup = 3.250.000
        # grossup = 3.250.000 / 92.5%
        # grossup = 3.513.514

        # lapis 1
        if bruto_total_50 <= tax_level1.tax_dpp_max:
            grossup_rate = 100.0 - ((tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2)/2.0)
            # grossup_rate = 100.0 - ((tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2))
            pph21_lapis_1 = (bruto_total_50 * (tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2) / 100.0)
        else:
            pph21_lapis_1 = (tax_level1.tax_dpp_max * (tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2) / 100.0)

        # lapis 2
        if bruto_total_50 > tax_level2.tax_dpp_max:
            pph21_lapis_2 = ((tax_level2.tax_dpp_max - tax_level1.tax_dpp_max) * (tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2) / 100.0)
        elif bruto_total_50 > tax_level1.tax_dpp_max and bruto_total_50 <= tax_level2.tax_dpp_max:
            grossup_rate = 100.0 - ((tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2)/2.0)
            # grossup_rate = 100.0 - ((tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2))
            pph21_lapis_2 = ((bruto_total_50 - tax_level1.tax_dpp_max) * (tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2) / 100.0)

        # lapis 3
        if bruto_total_50 > tax_level3.tax_dpp_max:
            pph21_lapis_3 = ((tax_level3.tax_dpp_max - tax_level2.tax_dpp_max) * (tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2) / 100.0)
        elif bruto_total_50 > tax_level2.tax_dpp_max and bruto_total_50 <= tax_level3.tax_dpp_max:
            grossup_rate = 100.0 - ((tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2)/2.0)
            # grossup_rate = 100.0 - ((tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2))
            pph21_lapis_3 = ((bruto_total_50 - tax_level2.tax_dpp_max) * (tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2) / 100.0)

        # lapis 4
        if bruto_total_50 > tax_level4.tax_dpp_max:
            pph21_lapis_4 = ((tax_level4.tax_dpp_max - tax_level3.tax_dpp_max) * (tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2) / 100.0)
        elif bruto_total_50 > tax_level3.tax_dpp_max and bruto_total_50 <= tax_level4.tax_dpp_max:
            grossup_rate = 100.0 - ((tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2)/2.0)
            # grossup_rate = 100.0 - ((tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2))    
            pph21_lapis_4 = ((bruto_total_50 - tax_level3.tax_dpp_max) * (tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2) / 100.0)

        # lapis 5
        if bruto_total_50 > tax_level4.tax_dpp_max:
            grossup_rate = 100.0 - ((tax_level5.tax_rate if self.is_npwp else tax_level5.tax_rate2)/2.0)
            # grossup_rate = 100.0 - ((tax_level5.tax_rate if self.is_npwp else tax_level5.tax_rate2))
            pph21_lapis_5 = ((bruto_total_50 - tax_level4.tax_dpp_max) * (tax_level5.tax_rate if self.is_npwp else tax_level5.tax_rate2) / 100.0)

        pph21_total = pph21_lapis_1 + pph21_lapis_2 + pph21_lapis_3 + pph21_lapis_4 + pph21_lapis_5
        
        # 2023.06.05 - update grossup satu level tearing untuk MHTG
        grossup_total = pph21_total / grossup_rate * 100
        # grossup_total = bruto_total / grossup_rate * 100

        open('/opt/odoo16/logs/log_feedoctor.log','a+').write('\n bruto total:' + str(bruto_total))
        open('/opt/odoo16/logs/log_feedoctor.log','a+').write('\n pph21 total:' + str(pph21_total))
        open('/opt/odoo16/logs/log_feedoctor.log','a+').write('\n grossup rate:' + str(grossup_rate))

        pph21 = pph21_total - pph21_prev
        grossup = grossup_total - grossup_prev
        prev_bruto_total_50 = bruto_total_50

        # hitung lagi bruto setelah grossup
        bruto_total += grossup
        bruto_total_50 = bruto_total / 2
        pph21_lapis_1 = pph21_lapis_2 = pph21_lapis_3 = pph21_lapis_4 = pph21_lapis_5 = 0
        
        # lapis 1
        if bruto_total_50 <= tax_level1.tax_dpp_max:
            grossup_rate = 100.0 - ((tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2)/2.0)
            # grossup_rate = 100.0 - ((tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2))
            pph21_lapis_1 = (bruto_total_50 * (tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2) / 100.0)
        else:
            pph21_lapis_1 = (tax_level1.tax_dpp_max * (tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2) / 100.0)

        # lapis 2
        if bruto_total_50 > tax_level2.tax_dpp_max:
            pph21_lapis_2 = ((tax_level2.tax_dpp_max - tax_level1.tax_dpp_max) * (tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2) / 100.0)
        elif bruto_total_50 > tax_level1.tax_dpp_max and bruto_total_50 <= tax_level2.tax_dpp_max:
            grossup_rate = 100.0 - ((tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2)/2.0)
            # grossup_rate = 100.0 - ((tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2))
            pph21_lapis_2 = ((bruto_total_50 - tax_level1.tax_dpp_max) * (tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2) / 100.0)

        # lapis 3
        if bruto_total_50 > tax_level3.tax_dpp_max:
            pph21_lapis_3 = ((tax_level3.tax_dpp_max - tax_level2.tax_dpp_max) * (tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2) / 100.0)
        elif bruto_total_50 > tax_level2.tax_dpp_max and bruto_total_50 <= tax_level3.tax_dpp_max:
            grossup_rate = 100.0 - ((tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2)/2.0)
            # grossup_rate = 100.0 - ((tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2))
            pph21_lapis_3 = ((bruto_total_50 - tax_level2.tax_dpp_max) * (tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2) / 100.0)

        # lapis 4
        if bruto_total_50 > tax_level4.tax_dpp_max:
            pph21_lapis_4 = ((tax_level4.tax_dpp_max - tax_level3.tax_dpp_max) * (tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2) / 100.0)
        elif bruto_total_50 > tax_level3.tax_dpp_max and bruto_total_50 <= tax_level4.tax_dpp_max:
            grossup_rate = 100.0 - ((tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2)/2.0)
            # grossup_rate = 100.0 - ((tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2))
            pph21_lapis_4 = ((bruto_total_50 - tax_level3.tax_dpp_max) * (tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2) / 100.0)

        # lapis 5
        if bruto_total_50 > tax_level4.tax_dpp_max:
            grossup_rate = 100.0 - ((tax_level5.tax_rate if self.is_npwp else tax_level5.tax_rate2)/2.0)
            # grossup_rate = 100.0 - ((tax_level5.tax_rate if self.is_npwp else tax_level5.tax_rate2))
            pph21_lapis_5 = ((bruto_total_50 - tax_level4.tax_dpp_max) * (tax_level5.tax_rate if self.is_npwp else tax_level5.tax_rate2) / 100.0)

        pph21_total = pph21_lapis_1 + pph21_lapis_2 + pph21_lapis_3 + pph21_lapis_4 + pph21_lapis_5
        pph21 = pph21_total - pph21_prev
        grossup_selisih = grossup - pph21

        # jika grossup ada selisih dengan pph21
        if grossup_selisih > 0 or grossup_selisih < 0:
            grossup_tambahan = grossup_selisih / grossup_rate * 100.0 * -1.0

        # tambah adjustment ke grossup
        grossup += grossup_tambahan
        return grossup
        #return grossup_tambahan

    # @api.multi
    def compute_pph21(self, bruto=0, bruto_prev=0, pph21_prev=0):
        tax_level1 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',1)], limit=1)
        tax_level2 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',2)], limit=1)
        tax_level3 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',3)], limit=1)
        tax_level4 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',4)], limit=1)
        tax_level5 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',5)], limit=1)
        
        total_bruto = bruto + bruto_prev
        total_bruto_50 = total_bruto / 2
        pph_21 = pph_lapis_1 = pph_lapis_2 = pph_lapis_3 = pph_lapis_4 = pph_lapis_5 = 0

        # hitung pph lapis 1
        if total_bruto_50 <= tax_level1.tax_dpp_max:
            pph_lapis_1 = (total_bruto_50 * (tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2) / 100.0)
        else:
            pph_lapis_1 = (tax_level1.tax_dpp_max * (tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2) / 100.0)

        # hitung pph lapis 2
        if total_bruto_50 > tax_level2.tax_dpp_max:
            pph_lapis_2 = ((tax_level2.tax_dpp_max - tax_level1.tax_dpp_max) * (tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2) / 100.0)
        elif total_bruto_50 > tax_level1.tax_dpp_max and total_bruto_50 <= tax_level2.tax_dpp_max:
            pph_lapis_2 = ((total_bruto_50 - tax_level1.tax_dpp_max) * (tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2) / 100.0)

        # hitung pph lapis 3
        if total_bruto_50 > tax_level3.tax_dpp_max:
            pph_lapis_3 = ((tax_level3.tax_dpp_max - tax_level2.tax_dpp_max) * (tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2) / 100.0)
        elif total_bruto_50 > tax_level2.tax_dpp_max and total_bruto_50 <= tax_level3.tax_dpp_max:
            pph_lapis_3 = ((total_bruto_50 - tax_level2.tax_dpp_max) * (tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2) / 100.0)

        # hitung pph lapis 4
        if total_bruto_50 > tax_level4.tax_dpp_max:
            pph_lapis_4 = ((tax_level4.tax_dpp_max - tax_level3.tax_dpp_max) * (tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2) / 100.0)
        elif total_bruto_50 > tax_level3.tax_dpp_max and total_bruto_50 <= tax_level4.tax_dpp_max:
            pph_lapis_4 = ((total_bruto_50 - tax_level3.tax_dpp_max) * (tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2) / 100.0)

        # hitung pph lapis 5
        if total_bruto_50 > tax_level4.tax_dpp_max:
            pph_lapis_5 = ((total_bruto_50 - tax_level4.tax_dpp_max) * (tax_level5.tax_rate if self.is_npwp else tax_level5.tax_rate2) / 100.0)

        # hitung PPh bulan ini adalah total PPH dikurangi PPH yg sudah dibayar bulan sebelumnya
        pph_21 = (pph_lapis_1 + pph_lapis_2 + pph_lapis_3 + pph_lapis_4 + pph_lapis_5) - pph21_prev
        return pph_21

    # @api.multi
    def compute_bruto(self):
        if self.sync_type == '9':
            self._compute_bruto_mhns()
        else:
            self._compute_bruto()

    def _compute_bruto_mhns(self):
        doc_rate = self.env['doctor.rate'].search([('doctor_id', '=', self.doctor_id.id)], limit=1)
        tax_level1 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',1)], limit=1)
        tax_level2 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',2)], limit=1)
        tax_level3 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',3)], limit=1)
        tax_level4 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',4)], limit=1)
        tax_level5 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',5)], limit=1)
        tax_pph23 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph23')], limit=1)
        
        # jika doctor_rate ada dan status masih draft
        if doc_rate and self.state == 'draft':
            year = self.year
            month = self.month

            # self.is_pot_gp = doc_rate.is_pot_gp
            # self.is_pot_total = doc_rate.is_pot_total

            # self.is_p12 = doc_rate.is_p12 
            # self.is_p12_total = doc_rate.is_p12_total 

            # self.is_igd = doc_rate.is_igd 
            # self.is_igd_total = doc_rate.is_igd_total

            # self.is_tnc = doc_rate.is_tnc 
            # self.is_tnc_total = doc_rate.is_tnc_total

            # self.is_pengirim = doc_rate.is_pengirim 
            # self.is_pengirim_total = doc_rate.is_pengirim_total

            # self.is_hd = doc_rate.is_hd
            # self.is_hd_total = doc_rate.is_hd_total

            self.is_pot_gp = False
            self.is_pot_total = False

            self.is_p12 = False
            self.is_p12_total = False

            self.is_igd = False 
            self.is_igd_total = False

            self.is_tnc = False 
            self.is_tnc_total = False

            self.is_pengirim = False
            self.is_pengirim_total = False

            self.is_hd = False
            self.is_hd_total = False

            self.is_dental = doc_rate.is_dental
            self.is_external = doc_rate.is_external
            self.is_grossup = doc_rate.is_grossup
            self.is_npwp = doc_rate.is_npwp
            self.npwp = doc_rate.npwp
            
            self.join_date = doc_rate.join_date

            gf = doc_rate.guarantee_fee 
            allowance = doc_rate.allowance
            if (gf > 0 or allowance > 0) and doc_rate.join_prorate is True:
                join_date = datetime.datetime.strptime(doc_rate.join_date, '%Y-%m-%d') 
                start_date = str(self.year) + '-' + ('00' + str(self.month))[-2:] + '-01'
                start_date = datetime.datetime.strptime(start_date, '%Y-%m-%d')
                end_date = start_date + relativedelta(months=1) - relativedelta(days=1)
                open('/opt/odoo16/logs/log_doctor_fee2.log','a+').write('\n' + str(join_date))

                if start_date < join_date:
                    day_total = (end_date - start_date).days
                    day_actual = (end_date - join_date).days
                    if day_actual < 0:
                        day_actual = 0
                    open('/opt/odoo16/logs/log_doctor_fee.log','a+').write('\nday_total: ' + str(day_total))
                    open('/opt/odoo16/logs/log_doctor_fee.log','a+').write('\nday_actual: ' + str(day_actual))
                    gf = float(day_actual or 0.0) / float(day_total or 0.0) * float(doc_rate.guarantee_fee or 0.0)
                    allowance = float(day_actual or 0.0) / float(day_total or 0.0) * float(doc_rate.allowance or 0.0)
                    open('/opt/odoo16/logs/log_doctor_fee.log','a+').write('\n\n' + str(gf))
                
            self.gf = gf
            self.allowance = allowance

            # self.gross_fee = 0
            self.total_fee = 0
            self.gross_up = 0
            self.total = 0
            self.previous_bruto = 0
            self.previous_pph21 = 0
            self.previous_grossup = 0
            # self.bruto = 0
            self.dpp = 0
            self.total_nett = 0
            self.thp = 0

            gf = self.gf
            is_bruto_diatas_gf = False
            is_total_diatas_gf = False

            # jika doctor tampungan untuk POT
            if self.is_pot_total is True:
                self.gross_fee = 0
                self.total_fee = 0
                self.bruto = 0
                self.gross_up = 0

                self.total = 0
                self.dpp = 0
                self.dpp_50 = 0
                self.previous_bruto = 0
                self.pph_21 = 0

                # hitung semua pot_share dari fee.line untuk semua doctor yang di centang sebagai POT/GP
                fee_line = self.env['doctor.fee.line'].search([('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month),('is_pot_gp', '=', True),('is_bpjs', '=', False)])
                for fee in fee_line:
                    rate_pot = fee.rate_pot
                    self.gross_fee += rate_pot
                self.total_fee = self.gross_fee
                self.total = self.gross_fee + self.other

                self.bruto = self.total_fee
                self.dpp = self.total
                self.dpp_50 = (self.dpp / 2)
                self.total_nett = self.total
                self.thp = self.total + self.deduction
            
            # jika doctor tampungan untuk P1/P2
            elif self.is_p12_total is True:
                self.gross_fee = 0
                self.total_fee = 0
                self.bruto = 0
                self.gross_up = 0

                self.total = 0
                self.dpp = 0
                self.dpp_50 = 0
                self.previous_bruto = 0
                self.pph_21 = 0

                # hitung semua p12_share dari fee.line untuk semua doctor yang di centang sebagai P1/P2
                fee_line = self.env['doctor.fee.line'].search([('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month),('is_p12', '=', True),('is_bpjs', '=', False)])
                for fee in fee_line:
                    rate_p12 = fee.rate_p12
                    self.gross_fee += rate_p12

                self.total_fee = self.gross_fee
                self.total = self.gross_fee + self.other
                self.bruto = self.total_fee
                self.dpp = self.total
                self.dpp_50 = (self.dpp / 2)
                self.total_nett = self.total
                self.thp = self.total + self.deduction

            # jika doctor tampungan untuk IGD
            elif self.is_igd_total is True:
                self.gross_fee = 0
                self.total_fee = 0
                self.bruto = 0
                self.gross_up = 0

                self.total = 0
                self.dpp = 0
                self.dpp_50 = 0
                self.previous_bruto = 0
                self.pph_21 = 0

                # hitung semua p12_share dari fee.line untuk semua doctor yang di centang sebagai P1/P2
                fee_line = self.env['doctor.fee.line'].search([('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month),('is_igd', '=', True),('is_bpjs', '=', False)])
                for fee in fee_line:
                    rate_igd = fee.rate_igd
                    self.gross_fee += rate_igd

                self.total_fee = self.gross_fee
                self.total = self.gross_fee + self.other
                self.bruto = self.total_fee
                self.dpp = self.total
                self.dpp_50 = (self.dpp / 2)
                self.total_nett = self.total
                self.thp = self.total + self.deduction

            # jika doctor tampungan untuk TNC
            elif self.is_tnc_total is True:
                self.gross_fee = 0
                self.total_fee = 0
                self.bruto = 0
                self.gross_up = 0

                self.total = 0
                self.dpp = 0
                self.dpp_50 = 0
                self.previous_bruto = 0
                self.pph_21 = 0

                # hitung semua tnc_share dari fee.line untuk semua doctor yang di centang sebagai TNC
                fee_line = self.env['doctor.fee.line'].search([('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month),('is_tnc', '=', True),('is_bpjs', '=', False)])
                for fee in fee_line:
                    rate_tnc = fee.rate_tnc
                    self.gross_fee += rate_tnc

                self.total_fee = self.gross_fee
                self.total = self.gross_fee + self.other
                self.bruto = self.total_fee
                self.dpp = self.total
                self.dpp_50 = (self.dpp / 2)
                self.total_nett = self.total
                self.thp = self.total + self.deduction
            
            # jika doctor tampungan untuk pengirim
            elif self.is_pengirim_total is True:
                self.gross_fee = 0
                self.total_fee = 0
                self.bruto = 0
                self.gross_up = 0

                self.total = 0
                self.dpp = 0
                self.dpp_50 = 0
                self.previous_bruto = 0
                self.pph_21 = 0

                # hitung semua pengirim_share dari fee.line untuk semua doctor yang di centang sebagai Pengirim
                fee_line = self.env['doctor.fee.line'].search([('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month),('is_pengirim', '=', True),('is_bpjs', '=', False)])
                for fee in fee_line:
                    rate_pengirim = fee.rate_pengirim
                    self.gross_fee += rate_pengirim

                self.total_fee = self.gross_fee
                self.total = self.gross_fee + self.other
                self.bruto = self.total_fee
                self.dpp = self.total
                self.dpp_50 = (self.dpp / 2)
                self.total_nett = self.total
                self.thp = self.total + self.deduction

            # jika doctor tampungan untuk HD
            elif self.is_hd_total is True:
                self.gross_fee = 0
                self.total_fee = 0
                self.bruto = 0
                self.gross_up = 0

                self.total = 0
                self.dpp = 0
                self.dpp_50 = 0
                self.previous_bruto = 0
                self.pph_21 = 0

                # hitung semua pengirim_share dari fee.line untuk semua doctor yang di centang sebagai Pengirim
                fee_line = self.env['doctor.fee.line'].search([('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month),('is_hd', '=', True),('is_bpjs', '=', False)])
                for fee in fee_line:
                    rate_hd = fee.rate_hd
                    self.gross_fee += rate_hd

                self.total_fee = self.gross_fee
                self.total = self.gross_fee + self.other
                self.bruto = self.total_fee
                self.dpp = self.total
                self.dpp_50 = (self.dpp / 2)
                self.total_nett = self.total
                self.thp = self.total + self.deduction

            # detail dokter normal (bukan tampungan)
            else:

                # 2021.09.22 recompute other/total
                self.other = 0
                self.gf_other = 0
                for line in self.other_transaction_ids:
                    if line.credit_gf:
                        self.gf_other += line.amount
                    else:
                        self.other += line.amount


                # 2021.09.22 recompute deduction
                self.deduction = 0
                for line in self.deduction_transaction_ids:
                    self.deduction += line.amount
                self.deduction *= -1


                # 2023.01.04 recompute total accrual BPJS
                self.total_accrual = 0
                for line in self.accrual_ids:
                    self.total_accrual += line.rate_accrual

                
                # jika POT GP maka hitung shareing fee GP, tambahkan ke bruto
                if self.is_pot_gp and self.is_pot_total is not True:
                    pot_total = self.env['doctor.fee'].search([('is_pot_total', '=', True),('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month)])
                    if pot_total:
                        self.pot_total_share = pot_total.thp
                        self.pot_total_point = pot_total.pot_total_point

                    if self.pot_point > 0 and self.pot_total_point > 0:
                        self.pot_share = (self.pot_point /self.pot_total_point *self.pot_total_share)
                    else:
                        self.pot_share = 0
                else:
                    self.pot_total_share = 0
                    self.pot_total_point = 0
                self.bruto += self.pot_share



                # 2023.03.15 jika P1/P2 maka hitung shareing fee P1/P2, tambahkan ke bruto
                if self.is_p12 and self.is_p12_total is not True:
                    p12_total = self.env['doctor.fee'].search([('is_p12_total', '=', True),('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month)])
                    if p12_total:
                        self.p12_total_share = p12_total.thp
                        self.p12_total_point = p12_total.p12_total_point

                    if self.p12_point > 0 and self.p12_total_point > 0:
                        self.p12_share = (self.p12_point /self.p12_total_point * self.p12_total_share)
                    else:
                        self.p12_share = 0
                else:
                    self.p12_total_share = 0
                    self.p12_total_point = 0
                self.bruto += self.p12_share


                # 2023.03.15 jika IGD maka hitung shareing fee IGD, tambahkan ke bruto
                if self.is_igd and self.is_igd_total is not True:
                    igd_total = self.env['doctor.fee'].search([('is_igd_total', '=', True),('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month)])
                    if igd_total:
                        self.igd_total_share = igd_total.thp
                        self.igd_total_point = igd_total.igd_total_point

                    if self.igd_point > 0 and self.igd_total_point > 0:
                        self.igd_share = (self.igd_point /self.igd_total_point * self.igd_total_share)
                    else:
                        self.igd_share = 0
                else:
                    self.igd_total_share = 0
                    self.igd_total_point = 0
                self.bruto += self.igd_share


                # 2023.04.09 jika Pengirim maka hitung shareing fee Pengirim/Referral, tambahkan ke bruto
                if self.is_pengirim and self.is_pengirim_total is not True:
                    pengirim_total = self.env['doctor.fee'].search([('is_pengirim_total', '=', True),('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month)])
                    if pengirim_total:
                        self.pengirim_total_share = pengirim_total.thp
                        self.pengirim_total_point = pengirim_total.pengirim_total_point

                    if self.pengirim_point > 0 and self.pengirim_total_point > 0:
                        self.pengirim_share = (self.pengirim_point /self.pengirim_total_point * self.pengirim_total_share)
                    else:
                        self.pengirim_share = 0
                else:
                    self.pengirim_total_share = 0
                    self.pengirim_total_point = 0
                self.bruto += self.pengirim_share


                # 2023.03.15 jika TNC maka hitung shareing fee TNC, tambahkan ke bruto
                if self.is_tnc and self.is_tnc_total is not True:
                    tnc_total = self.env['doctor.fee'].search([('is_tnc_total', '=', True),('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month)])
                    if tnc_total:
                        self.tnc_total_share = tnc_total.thp
                        self.tnc_total_point = tnc_total.tnc_total_point

                    if self.tnc_point > 0 and self.tnc_total_point > 0:
                        self.tnc_share = (self.tnc_point /self.tnc_total_point * self.tnc_total_share)
                    else:
                        self.tnc_share = 0
                else:
                    self.tnc_total_share = 0
                    self.tnc_total_point = 0
                self.bruto += self.tnc_share


                # 2023.03.15 jika HD maka hitung shareing fee HD, tambahkan ke bruto
                if self.is_hd and self.is_hd_total is not True:
                    hd_total = self.env['doctor.fee'].search([('is_hd_total', '=', True),('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month)])
                    if hd_total:
                        self.hd_total_share = hd_total.thp
                        self.hd_total_point = hd_total.hd_total_point

                    if self.hd_point > 0 and self.hd_total_point > 0:
                        self.hd_share = (self.hd_point /self.hd_total_point * self.hd_total_share)
                    else:
                        self.hd_share = 0
                else:
                    self.hd_total_share = 0
                    self.hd_total_point = 0
                self.bruto += self.hd_share


                # tambahkan nilai bruto & gross_fee looping semua fee.line
                # rate fee >= 50% maka bruto ambil dari nilai billing/revenue
                # rate fee < 50% maka bruto ambil dari nilai fee
                if self.transaction_ids:
                    for tl in self.transaction_ids:
                        rate = tl.rate
                        total = tl.total
                        self.gross_fee += rate
                        
                        # 2021.07.07 jika MHKN maka bruto dihitung dari fee amount per tindakan
                        # if self.company_id.sync_type == '6':
                        #     self.bruto += rate
                        # selain MHKN
                        # else:
                        #     if tl.rate_percent >= 50 and tl.rate > 0:
                        #         self.bruto += tl.total
                        #     elif tl.rate_percent > 0 and tl.rate_percent < 50 and tl.rate > 0:
                        #         self.bruto += rate

                        if self.company_id.sync_type == '6':
                            self.bruto += rate
                        elif self.company_id.sync_type == '7':
                            self.bruto += total
                        # jika dokter TNC MHTG maka ambil DPP dari Jasa Dokter
                        elif self.company_id.sync_type == '2' and self.is_tnc is True:
                            self.bruto += rate

                        elif self.is_dental is True or self.is_external:
                            self.bruto += rate
                        elif tl.rate_percent >= 50 and tl.rate > 0:
                            if tl.rate_percent <= 100:
                                self.bruto += tl.total
                            else:
                                # jika ada rate yang lebih 100%, rate langsung dari amount
                                # maka ambil bruto dari nilai rate
                                if tl.total == 0:
                                    self.bruto += rate
                                # selain itu
                                else:
                                    # jika persentase fee amount/total lebih besar sama dengan 50% 
                                    # ambil bruto dari bill_amount
                                    if (float(tl.rate/tl.total) * 100.0) >= 50.0:
                                        self.bruto += tl.total
                                    # jika kurang dari 50%
                                    # ambil dari rate amount
                                    else:
                                        self.bruto += rate 
                        elif tl.rate_percent > 0 and tl.rate_percent < 50 and tl.rate > 0:
                            self.bruto += rate
                        else:
                            # rate 0, ada fee_amount, maka hitung bruto dari fee amount
                            # khusus MHJS yang rate 0, fee_amount > 0, maka tidak dihitung sebagai bruto tax/pph
                            if self.company_id.sync_type not in ['1']:
                                self.bruto += rate

                # gabung total fee = gross_fee + addition fee + pot share fee
                self.total_fee = self.gross_fee + self.other + self.pot_share + self.p12_share + self.igd_share + self.pengirim_share + self.tnc_share + self.hd_share
                # jika total fee dibawah GF, maka masukin fee sebagai total fee
                if (self.total_fee - self.pph_21) <= gf and gf > 0:
                    self.total_fee = gf
                else:
                    is_total_diatas_gf = True

                # tambahakn addition fee ke bruto
                self.bruto += self.other
                # jika bruto dibawah GF, maka masukan nilai GF sebagai bruto
                if self.bruto <= gf:
                    self.bruto = gf
                else:
                    is_bruto_diatas_gf = True

                # 2021.08.03 case MHKN GF ada potongan absensi u/ bruto dibawah GF
                if is_total_diatas_gf is not True and self.gf > 0:
                    gf += self.gf_other
                    self.total_fee = gf
                    self.bruto = gf

                # allowance setelah GF
                self.total_fee += self.allowance
                self.bruto += self.allowance

                # hitung total previous Bruto, PPH dan Gross UP (jika ada)
                previous_pph21 = 0
                previous_grossup = 0
                sisa_gf = 0

                # # looping transaksi bulan sebelumya jika bukan bulan januari
                # if int(month) > 1:
                #     sale = self.env['doctor.fee'].search([('doctor_id', '=', self.doctor_id.id),('company_id', '=', self.company_id.id),('year', '=', year), ('month', '<', month),('state', 'in', ['confirmed','posted'])])
                #     for tl in sale:
                #         self.previous_bruto += tl.dpp
                #         self.previous_pph21 += tl.pph_21
                #         previous_pph21 += tl.pph_21
                #         # 20210707 - jika grossup fee aktif
                #         if self.is_grossup:
                #             previous_grossup += tl.gross_up

                # jika bruto bukan NOL
                if self.bruto > 0:
                    # jika dokter mendapat nilai GF maka lakukan grossup pada fee
                    if gf > 0 and is_total_diatas_gf is not True:
                        self.bruto = self.total_fee  #jika ada GF maka bruto sesuai dengan nilai GF
                        # 20210707 - jika grossup aktif
                        if self.is_grossup:
                            self.gross_up = self.compute_grossup(self.bruto, self.previous_bruto, previous_pph21, previous_grossup)
                    
                    elif gf > 0 and is_total_diatas_gf is True:
                        pph21_dari_bruto = self.compute_pph21(self.bruto, self.previous_bruto, previous_pph21)
                        total_fee_nett = self.total_fee - pph21_dari_bruto
                        if (total_fee_nett < gf) and self.is_grossup:
                            is_total_diatas_gf = False
                            self.bruto = gf

                    # 20210707 - jika grossup aktif
                    elif self.is_grossup:
                        self.gross_up = self.compute_grossup(self.bruto, self.previous_bruto, previous_pph21, previous_grossup)
                    # raise exceptions.ValidationError(self.gross_up)

                    # jika total fee sudah diatas GF
                    # maka gross up hanya kekurangan jika ada kekurangan PPH
                    if is_total_diatas_gf and gf > 0:
                        sisa_gf = self.total_fee - gf
                        # 20210707 - jika grossup aktif
                        if self.is_grossup:
                            self.gross_up -= sisa_gf

                    # grossup tidak boleh dibawah NOL
                    if self.gross_up < 0:
                        self.gross_up = 0

                # simoan total bruto & fee setelah grossup
                self.total = self.total_fee + self.gross_up
                self.dpp = self.bruto + self.gross_up #+ sisa_gf
                self.dpp_50 = self.dpp / 2

                # hitung PPH sesuai teiring bruto 50%
                total_bruto = self.dpp + self.previous_bruto
                total_bruto_50 = total_bruto / 2
                pph_lapis_1 = pph_lapis_2 = pph_lapis_3 = pph_lapis_4 = pph_lapis_5 = 0

                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n\n\n Total Bruto: ' + str(total_bruto))
                # hitung pph lapis 1
                if total_bruto_50 <= tax_level1.tax_dpp_max:
                    self.lapis = '1'
                    pph_lapis_1 = total_bruto_50 * (tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2) / 100.0
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 1 Bruto 50%: ' + str(total_bruto_50))
                else:
                    pph_lapis_1 = tax_level1.tax_dpp_max * (tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2) / 100.0
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 1 Bruto 50%: ' + str(tax_level1.tax_dpp_max))
                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 1: ' + str(pph_lapis_1))

                # hitung pph lapis 2
                if total_bruto_50 > tax_level2.tax_dpp_max:
                    pph_lapis_2 = (tax_level2.tax_dpp_max - tax_level1.tax_dpp_max)  * (tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2) / 100.0
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 2 Bruto 50%: ' + str(tax_level2.tax_dpp_max-tax_level1.tax_dpp_max))
                elif total_bruto_50 > tax_level1.tax_dpp_max and total_bruto_50 <= tax_level2.tax_dpp_max:
                    self.lapis = '2'
                    pph_lapis_2 = ((total_bruto_50 - tax_level1.tax_dpp_max) * (tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2) / 100.0)
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 2 Bruto 50%: ' + str(total_bruto_50 - tax_level1.tax_dpp_max))
                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 2: ' + str(pph_lapis_2))

                # hitung pph  lapis 3
                if total_bruto_50 > tax_level3.tax_dpp_max:
                    pph_lapis_3 = (tax_level3.tax_dpp_max - tax_level2.tax_dpp_max) * (tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2) / 100.0
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 3 Bruto 50%: ' + str(tax_level3.tax_dpp_max-tax_level2.tax_dpp_max))
                elif total_bruto_50 > tax_level2.tax_dpp_max and total_bruto_50 <= tax_level3.tax_dpp_max:
                    self.lapis = '3'
                    pph_lapis_3 = ((total_bruto_50 - tax_level2.tax_dpp_max) * (tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2) / 100.0)
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 3 Bruto 50%: ' + str(total_bruto_50 - tax_level2.tax_dpp_max))
                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 3: ' + str(pph_lapis_3))

                # hitung pph lapis 4
                if total_bruto_50 > tax_level4.tax_dpp_max:
                    pph_lapis_4 = (tax_level4.tax_dpp_max - tax_level3.tax_dpp_max) * (tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2) / 100.0
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 4 Bruto 50%: ' + str(tax_level4.tax_dpp_max - tax_level3.tax_dpp_max))
                elif total_bruto_50 > tax_level3.tax_dpp_max and total_bruto_50 <= tax_level4.tax_dpp_max:
                    self.lapis = '4'
                    pph_lapis_4 = ((total_bruto_50 - tax_level3.tax_dpp_max) * (tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2) / 100.0)
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 4 Bruto 50%: ' + str(total_bruto_50 - tax_level3.tax_dpp_max))

                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 4: ' + str(pph_lapis_4))

                # hitung pph lapis 5
                if total_bruto_50 > tax_level4.tax_dpp_max:
                    self.lapis = '5'
                    pph_lapis_5 = ((total_bruto_50 - tax_level4.tax_dpp_max) * (tax_level5.tax_rate if self.is_npwp else tax_level5.tax_rate2) / 100.0)
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 5 Bruto 50%: ' + (total_bruto_50 - tax_level4.tax_dpp_max))
                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 5: ' + str(pph_lapis_5))
                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Previous: ' + str(previous_pph21))

                # 2021.08.04 perhitungan PPH 21 u/ Internal Doctor
                # hitung PPh bulan ini adalah total PPH dikurangi PPH yg sudah dibayar bulan sebelumnya
                if self.is_dental is not True and self.is_external is not True:
                    self.pph_21 = (pph_lapis_1 + pph_lapis_2 + pph_lapis_3 + pph_lapis_4 + pph_lapis_5) - previous_pph21
                # 2021.08.04 perhitungan PPH 23 % u/ Dental
                else:
                    # 2% untuk WP yg memiliki NPWP, 4% untuk yg tidak ada NPWP
                    self.pph_21 = (self.bruto *  ((tax_pph23.tax_rate if self.is_npwp else tax_pph23.tax_rate2)) / 100.0)

                # jika total fee grossup diatas nol
                if self.total > 0:
                    self.total_nett = self.total - self.pph_21
                    self.thp = self.total - self.pph_21 + self.deduction
            
        else:
            raise exceptions.ValidationError('Doctor rate ' + str(self.doctor_id.name) + ' not found!, please input doctor rate first.')



    def _compute_bruto(self):
        doc_rate = self.env['doctor.rate'].search([('doctor_id', '=', self.doctor_id.id)], limit=1)
        tax_level1 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',1)], limit=1)
        tax_level2 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',2)], limit=1)
        tax_level3 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',3)], limit=1)
        tax_level4 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',4)], limit=1)
        tax_level5 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph21'), ('tax_level','=',5)], limit=1)
        tax_pph23 = self.env['doctor.tax'].search([('company_id', '=', self.company_id.id), ('tax_type','=','pph23')], limit=1)
        
        # jika doctor_rate ada dan status masih draft
        if doc_rate and self.state == 'draft':
            year = self.year
            month = self.month

            self.is_pot_gp = doc_rate.is_pot_gp
            self.is_pot_total = doc_rate.is_pot_total

            self.is_p12 = doc_rate.is_p12 
            self.is_p12_total = doc_rate.is_p12_total 

            self.is_igd = doc_rate.is_igd 
            self.is_igd_total = doc_rate.is_igd_total

            self.is_tnc = doc_rate.is_tnc 
            self.is_tnc_total = doc_rate.is_tnc_total

            self.is_pengirim = doc_rate.is_pengirim 
            self.is_pengirim_total = doc_rate.is_pengirim_total

            self.is_hd = doc_rate.is_hd
            self.is_hd_total = doc_rate.is_hd_total

            self.is_dental = doc_rate.is_dental
            self.is_external = doc_rate.is_external
            self.is_grossup = doc_rate.is_grossup
            self.is_npwp = doc_rate.is_npwp
            self.npwp = doc_rate.npwp
            
            self.join_date = doc_rate.join_date

            gf = doc_rate.guarantee_fee 
            allowance = doc_rate.allowance
            if (gf > 0 or allowance > 0) and doc_rate.join_prorate is True:
                join_date = datetime.datetime.strptime(doc_rate.join_date, '%Y-%m-%d') 
                start_date = str(self.year) + '-' + ('00' + str(self.month))[-2:] + '-01'
                start_date = datetime.datetime.strptime(start_date, '%Y-%m-%d')
                end_date = start_date + relativedelta(months=1) - relativedelta(days=1)
                open('/opt/odoo16/logs/log_doctor_fee2.log','a+').write('\n' + str(join_date))

                if start_date < join_date:
                    day_total = (end_date - start_date).days
                    day_actual = (end_date - join_date).days
                    if day_actual < 0:
                        day_actual = 0
                    open('/opt/odoo16/logs/log_doctor_fee.log','a+').write('\nday_total: ' + str(day_total))
                    open('/opt/odoo16/logs/log_doctor_fee.log','a+').write('\nday_actual: ' + str(day_actual))
                    gf = float(day_actual or 0.0) / float(day_total or 0.0) * float(doc_rate.guarantee_fee or 0.0)
                    allowance = float(day_actual or 0.0) / float(day_total or 0.0) * float(doc_rate.allowance or 0.0)
                    open('/opt/odoo16/logs/log_doctor_fee.log','a+').write('\n\n' + str(gf))
                
            self.gf = gf
            self.allowance = allowance

            self.gross_fee = 0
            self.total_fee = 0
            self.gross_up = 0
            self.total = 0
            self.previous_bruto = 0
            self.previous_pph21 = 0
            self.previous_grossup = 0
            self.bruto = 0
            self.dpp = 0
            self.total_nett = 0
            self.thp = 0

            gf = self.gf
            is_bruto_diatas_gf = False
            is_total_diatas_gf = False

            # jika doctor tampungan untuk POT
            if self.is_pot_total is True:
                self.gross_fee = 0
                self.total_fee = 0
                self.bruto = 0
                self.gross_up = 0

                self.total = 0
                self.dpp = 0
                self.dpp_50 = 0
                self.previous_bruto = 0
                self.pph_21 = 0

                # hitung semua pot_share dari fee.line untuk semua doctor yang di centang sebagai POT/GP
                fee_line = self.env['doctor.fee.line'].search([('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month),('is_pot_gp', '=', True),('is_bpjs', '=', False)])
                for fee in fee_line:
                    rate_pot = fee.rate_pot
                    self.gross_fee += rate_pot
                self.total_fee = self.gross_fee
                self.total = self.gross_fee + self.other
                self.bruto = self.total_fee
                self.dpp = self.total
                self.dpp_50 = (self.dpp / 2)
                self.total_nett = self.total
                self.thp = self.total + self.deduction
            
            # jika doctor tampungan untuk P1/P2
            elif self.is_p12_total is True:
                self.gross_fee = 0
                self.total_fee = 0
                self.bruto = 0
                self.gross_up = 0

                self.total = 0
                self.dpp = 0
                self.dpp_50 = 0
                self.previous_bruto = 0
                self.pph_21 = 0

                # hitung semua p12_share dari fee.line untuk semua doctor yang di centang sebagai P1/P2
                fee_line = self.env['doctor.fee.line'].search([('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month),('is_p12', '=', True),('is_bpjs', '=', False)])
                for fee in fee_line:
                    rate_p12 = fee.rate_p12
                    self.gross_fee += rate_p12

                self.total_fee = self.gross_fee
                self.total = self.gross_fee + self.other
                self.bruto = self.total_fee
                self.dpp = self.total
                self.dpp_50 = (self.dpp / 2)
                self.total_nett = self.total
                self.thp = self.total + self.deduction

            # jika doctor tampungan untuk IGD
            elif self.is_igd_total is True:
                self.gross_fee = 0
                self.total_fee = 0
                self.bruto = 0
                self.gross_up = 0

                self.total = 0
                self.dpp = 0
                self.dpp_50 = 0
                self.previous_bruto = 0
                self.pph_21 = 0

                # hitung semua p12_share dari fee.line untuk semua doctor yang di centang sebagai P1/P2
                fee_line = self.env['doctor.fee.line'].search([('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month),('is_igd', '=', True),('is_bpjs', '=', False)])
                for fee in fee_line:
                    rate_igd = fee.rate_igd
                    self.gross_fee += rate_igd

                self.total_fee = self.gross_fee
                self.total = self.gross_fee + self.other
                self.bruto = self.total_fee
                self.dpp = self.total
                self.dpp_50 = (self.dpp / 2)
                self.total_nett = self.total
                self.thp = self.total + self.deduction

            # jika doctor tampungan untuk TNC
            elif self.is_tnc_total is True:
                self.gross_fee = 0
                self.total_fee = 0
                self.bruto = 0
                self.gross_up = 0

                self.total = 0
                self.dpp = 0
                self.dpp_50 = 0
                self.previous_bruto = 0
                self.pph_21 = 0

                # hitung semua tnc_share dari fee.line untuk semua doctor yang di centang sebagai TNC
                fee_line = self.env['doctor.fee.line'].search([('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month),('is_tnc', '=', True),('is_bpjs', '=', False)])
                for fee in fee_line:
                    rate_tnc = fee.rate_tnc
                    self.gross_fee += rate_tnc

                self.total_fee = self.gross_fee
                self.total = self.gross_fee + self.other
                self.bruto = self.total_fee
                self.dpp = self.total
                self.dpp_50 = (self.dpp / 2)
                self.total_nett = self.total
                self.thp = self.total + self.deduction
            
            # jika doctor tampungan untuk pengirim
            elif self.is_pengirim_total is True:
                self.gross_fee = 0
                self.total_fee = 0
                self.bruto = 0
                self.gross_up = 0

                self.total = 0
                self.dpp = 0
                self.dpp_50 = 0
                self.previous_bruto = 0
                self.pph_21 = 0

                # hitung semua pengirim_share dari fee.line untuk semua doctor yang di centang sebagai Pengirim
                fee_line = self.env['doctor.fee.line'].search([('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month),('is_pengirim', '=', True),('is_bpjs', '=', False)])
                for fee in fee_line:
                    rate_pengirim = fee.rate_pengirim
                    self.gross_fee += rate_pengirim

                self.total_fee = self.gross_fee
                self.total = self.gross_fee + self.other
                self.bruto = self.total_fee
                self.dpp = self.total
                self.dpp_50 = (self.dpp / 2)
                self.total_nett = self.total
                self.thp = self.total + self.deduction

            # jika doctor tampungan untuk HD
            elif self.is_hd_total is True:
                self.gross_fee = 0
                self.total_fee = 0
                self.bruto = 0
                self.gross_up = 0

                self.total = 0
                self.dpp = 0
                self.dpp_50 = 0
                self.previous_bruto = 0
                self.pph_21 = 0

                # hitung semua pengirim_share dari fee.line untuk semua doctor yang di centang sebagai Pengirim
                fee_line = self.env['doctor.fee.line'].search([('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month),('is_hd', '=', True),('is_bpjs', '=', False)])
                for fee in fee_line:
                    rate_hd = fee.rate_hd
                    self.gross_fee += rate_hd

                self.total_fee = self.gross_fee
                self.total = self.gross_fee + self.other
                self.bruto = self.total_fee
                self.dpp = self.total
                self.dpp_50 = (self.dpp / 2)
                self.total_nett = self.total
                self.thp = self.total + self.deduction

            # detail dokter normal (bukan tampungan)
            else:

                # 2021.09.22 recompute other/total
                self.other = 0
                self.gf_other = 0
                for line in self.other_transaction_ids:
                    if line.credit_gf:
                        self.gf_other += line.amount
                    else:
                        self.other += line.amount


                # 2021.09.22 recompute deduction
                self.deduction = 0
                for line in self.deduction_transaction_ids:
                    self.deduction += line.amount
                self.deduction *= -1


                # 2023.01.04 recompute total accrual BPJS
                self.total_accrual = 0
                for line in self.accrual_ids:
                    self.total_accrual += line.rate_accrual

                
                # jika POT GP maka hitung shareing fee GP, tambahkan ke bruto
                if self.is_pot_gp and self.is_pot_total is not True:
                    pot_total = self.env['doctor.fee'].search([('is_pot_total', '=', True),('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month)])
                    if pot_total:
                        self.pot_total_share = pot_total.thp
                        self.pot_total_point = pot_total.pot_total_point

                    if self.pot_point > 0 and self.pot_total_point > 0:
                        self.pot_share = (self.pot_point /self.pot_total_point *self.pot_total_share)
                    else:
                        self.pot_share = 0
                else:
                    self.pot_total_share = 0
                    self.pot_total_point = 0

                ################################################################
                if self.company_id.sync_type not in ['8']:
                    self.bruto += self.pot_share



                # 2023.03.15 jika P1/P2 maka hitung shareing fee P1/P2, tambahkan ke bruto
                if self.is_p12 and self.is_p12_total is not True:
                    p12_total = self.env['doctor.fee'].search([('is_p12_total', '=', True),('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month)])
                    if p12_total:
                        self.p12_total_share = p12_total.thp
                        self.p12_total_point = p12_total.p12_total_point

                    if self.p12_point > 0 and self.p12_total_point > 0:
                        self.p12_share = (self.p12_point /self.p12_total_point * self.p12_total_share)
                    else:
                        self.p12_share = 0
                else:
                    self.p12_total_share = 0
                    self.p12_total_point = 0
                self.bruto += self.p12_share


                # 2023.03.15 jika IGD maka hitung shareing fee IGD, tambahkan ke bruto
                if self.is_igd and self.is_igd_total is not True:
                    igd_total = self.env['doctor.fee'].search([('is_igd_total', '=', True),('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month)])
                    if igd_total:
                        self.igd_total_share = igd_total.thp
                        self.igd_total_point = igd_total.igd_total_point

                    if self.igd_point > 0 and self.igd_total_point > 0:
                        self.igd_share = (self.igd_point /self.igd_total_point * self.igd_total_share)
                    else:
                        self.igd_share = 0
                else:
                    self.igd_total_share = 0
                    self.igd_total_point = 0
                self.bruto += self.igd_share


                # 2023.04.09 jika Pengirim maka hitung shareing fee Pengirim/Referral, tambahkan ke bruto
                if self.is_pengirim and self.is_pengirim_total is not True:
                    pengirim_total = self.env['doctor.fee'].search([('is_pengirim_total', '=', True),('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month)])
                    if pengirim_total:
                        self.pengirim_total_share = pengirim_total.thp
                        self.pengirim_total_point = pengirim_total.pengirim_total_point

                    if self.pengirim_point > 0 and self.pengirim_total_point > 0:
                        self.pengirim_share = (self.pengirim_point /self.pengirim_total_point * self.pengirim_total_share)
                    else:
                        self.pengirim_share = 0
                else:
                    self.pengirim_total_share = 0
                    self.pengirim_total_point = 0
                self.bruto += self.pengirim_share


                # 2023.03.15 jika TNC maka hitung shareing fee TNC, tambahkan ke bruto
                if self.is_tnc and self.is_tnc_total is not True:
                    tnc_total = self.env['doctor.fee'].search([('is_tnc_total', '=', True),('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month)])
                    if tnc_total:
                        self.tnc_total_share = tnc_total.thp
                        self.tnc_total_point = tnc_total.tnc_total_point

                    if self.tnc_point > 0 and self.tnc_total_point > 0:
                        self.tnc_share = (self.tnc_point /self.tnc_total_point * self.tnc_total_share)
                    else:
                        self.tnc_share = 0
                else:
                    self.tnc_total_share = 0
                    self.tnc_total_point = 0
                self.bruto += self.tnc_share


                # 2023.03.15 jika HD maka hitung shareing fee HD, tambahkan ke bruto
                if self.is_hd and self.is_hd_total is not True:
                    hd_total = self.env['doctor.fee'].search([('is_hd_total', '=', True),('company_id', '=', self.company_id.id),('year', '=', self.year), ('month', '=', self.month)])
                    if hd_total:
                        self.hd_total_share = hd_total.thp
                        self.hd_total_point = hd_total.hd_total_point

                    if self.hd_point > 0 and self.hd_total_point > 0:
                        self.hd_share = (self.hd_point /self.hd_total_point * self.hd_total_share)
                    else:
                        self.hd_share = 0
                else:
                    self.hd_total_share = 0
                    self.hd_total_point = 0
                self.bruto += self.hd_share


                # tambahkan nilai bruto & gross_fee looping semua fee.line
                # rate fee >= 50% maka bruto ambil dari nilai billing/revenue
                # rate fee < 50% maka bruto ambil dari nilai fee
                if self.transaction_ids:
                    for tl in self.transaction_ids:
                        rate = tl.rate
                        total = tl.total
                        self.gross_fee += rate
                        
                        # 2021.07.07 jika MHKN maka bruto dihitung dari fee amount per tindakan
                        # if self.company_id.sync_type == '6':
                        #     self.bruto += rate
                        # selain MHKN
                        # else:
                        #     if tl.rate_percent >= 50 and tl.rate > 0:
                        #         self.bruto += tl.total
                        #     elif tl.rate_percent > 0 and tl.rate_percent < 50 and tl.rate > 0:
                        #         self.bruto += rate

                        #if self.company_id.sync_type == '6':
                        #    self.bruto += rate # 2025.01.24 - request ervin bruto ambil dari total
                        if self.company_id.sync_type == '7':
                            self.bruto += total
                        # jika dokter TNC MHTG maka ambil DPP dari Jasa Dokter
                        elif self.company_id.sync_type == '2' and self.is_tnc is True:
                            self.bruto += rate

                        elif self.is_dental is True or self.is_external:
                            self.bruto += rate
                        elif tl.rate_percent >= 50 and tl.rate > 0:
                            if tl.rate_percent <= 100:
                                self.bruto += tl.total
                            else:
                                # jika ada rate yang lebih 100%, rate langsung dari amount
                                # maka ambil bruto dari nilai rate
                                if tl.total == 0:
                                    self.bruto += rate
                                # selain itu
                                else:
                                    # jika persentase fee amount/total lebih besar sama dengan 50% 
                                    # ambil bruto dari bill_amount
                                    if (float(tl.rate/tl.total) * 100.0) >= 50.0:
                                        self.bruto += tl.total
                                    # jika kurang dari 50%
                                    # ambil dari rate amount
                                    else:
                                        self.bruto += rate 
                        elif tl.rate_percent > 0 and tl.rate_percent < 50 and tl.rate > 0:
                            self.bruto += rate
                        else:
                            # rate 0, ada fee_amount, maka hitung bruto dari fee amount
                            # khusus MHJS yang rate 0, fee_amount > 0, maka tidak dihitung sebagai bruto tax/pph
                            if self.company_id.sync_type not in ['1']:
                                self.bruto += rate

                

                # gabung total fee = gross_fee + addition fee + pot share fee
                self.total_fee = self.gross_fee + self.other + self.pot_share + self.p12_share + self.igd_share + self.pengirim_share + self.tnc_share + self.hd_share

                

                # jika total fee dibawah GF, maka masukin fee sebagai total fee
                # if (self.total_fee - self.pph_21) <= gf and gf > 0:
                if (self.total_fee <= gf or ((self.total_fee - self.pph_21) <= gf) and self.gross_up is True) and gf > 0:
                    self.total_fee = gf
                else:
                    is_total_diatas_gf = True

                # tambahakn addition fee ke bruto
                self.bruto += self.other
                # jika bruto dibawah GF, maka masukan nilai GF sebagai bruto
                if self.bruto <= gf:
                    self.bruto = gf
                else:
                    is_bruto_diatas_gf = True

                # 2021.08.03 case MHKN GF ada potongan absensi u/ bruto dibawah GF
                if is_total_diatas_gf is not True and self.gf > 0:
                    gf += self.gf_other
                    self.total_fee = gf
                    self.bruto = gf

                # allowance setelah GF
                self.total_fee += self.allowance
                self.bruto += self.allowance

                # hitung total previous Bruto, PPH dan Gross UP (jika ada)
                previous_pph21 = 0
                previous_grossup = 0
                sisa_gf = 0

                # looping transaksi bulan sebelumya jika bukan bulan januari
                # per 2024, perhitungan PPH 21 jasa dokter rate bruto reset per bulan
                # if month > 1:
                #     sale = self.env['doctor.fee'].search([('doctor_id', '=', self.doctor_id.id),('company_id', '=', self.company_id.id),('year', '=', year), ('month', '<', month),('state', 'in', ['confirmed','posted'])])
                #     for tl in sale:
                #         self.previous_bruto += tl.dpp
                #         self.previous_pph21 += tl.pph_21
                #         previous_pph21 += tl.pph_21
                #         # 20210707 - jika grossup fee aktif
                #         if self.is_grossup:
                #             previous_grossup += tl.gross_up

                # jika bruto bukan NOL
                if self.bruto > 0:
                    # jika dokter mendapat nilai GF maka lakukan grossup pada fee
                    if gf > 0 and is_total_diatas_gf is not True:
                        self.bruto = self.total_fee  #jika ada GF maka bruto sesuai dengan nilai GF
                        # 20210707 - jika grossup aktif
                        if self.is_grossup:
                            self.gross_up = self.compute_grossup(self.bruto, self.previous_bruto, previous_pph21, previous_grossup)
                    
                    elif gf > 0 and is_total_diatas_gf is True:
                        pph21_dari_bruto = self.compute_pph21(self.bruto, self.previous_bruto, previous_pph21)
                        total_fee_nett = self.total_fee - pph21_dari_bruto
                        if (total_fee_nett < gf) and self.is_grossup:
                            is_total_diatas_gf = False
                            self.bruto = gf

                    # 20210707 - jika grossup aktif
                    elif self.is_grossup:
                        self.gross_up = self.compute_grossup(self.bruto, self.previous_bruto, previous_pph21, previous_grossup)
                    # raise exceptions.ValidationError(self.gross_up)

                    # jika total fee sudah diatas GF
                    # maka gross up hanya kekurangan jika ada kekurangan PPH
                    if is_total_diatas_gf and gf > 0:
                        sisa_gf = self.total_fee - gf
                        # 20210707 - jika grossup aktif
                        if self.is_grossup:
                            self.gross_up -= sisa_gf

                    # grossup tidak boleh dibawah NOL
                    if self.gross_up < 0:
                        self.gross_up = 0

                # simoan total bruto & fee setelah grossup
                self.total = self.total_fee + self.gross_up
                self.dpp = self.bruto + self.gross_up #+ sisa_gf
                self.dpp_50 = self.dpp / 2

                # hitung PPH sesuai teiring bruto 50%
                total_bruto = self.dpp + self.previous_bruto
                total_bruto_50 = total_bruto / 2
                pph_lapis_1 = pph_lapis_2 = pph_lapis_3 = pph_lapis_4 = pph_lapis_5 = 0

                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n\n\n Total Bruto: ' + str(total_bruto))
                # hitung pph lapis 1
                if total_bruto_50 <= tax_level1.tax_dpp_max:
                    self.lapis = '1'
                    pph_lapis_1 = total_bruto_50 * (tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2) / 100.0
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 1 Bruto 50%: ' + str(total_bruto_50))
                else:
                    pph_lapis_1 = tax_level1.tax_dpp_max * (tax_level1.tax_rate if self.is_npwp else tax_level1.tax_rate2) / 100.0
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 1 Bruto 50%: ' + str(tax_level1.tax_dpp_max))
                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 1: ' + str(pph_lapis_1))

                # hitung pph lapis 2
                if total_bruto_50 > tax_level2.tax_dpp_max:
                    pph_lapis_2 = (tax_level2.tax_dpp_max - tax_level1.tax_dpp_max)  * (tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2) / 100.0
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 2 Bruto 50%: ' + str(tax_level2.tax_dpp_max-tax_level1.tax_dpp_max))
                elif total_bruto_50 > tax_level1.tax_dpp_max and total_bruto_50 <= tax_level2.tax_dpp_max:
                    self.lapis = '2'
                    pph_lapis_2 = ((total_bruto_50 - tax_level1.tax_dpp_max) * (tax_level2.tax_rate if self.is_npwp else tax_level2.tax_rate2) / 100.0)
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 2 Bruto 50%: ' + str(total_bruto_50 - tax_level1.tax_dpp_max))
                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 2: ' + str(pph_lapis_2))

                # hitung pph  lapis 3
                if total_bruto_50 > tax_level3.tax_dpp_max:
                    pph_lapis_3 = (tax_level3.tax_dpp_max - tax_level2.tax_dpp_max) * (tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2) / 100.0
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 3 Bruto 50%: ' + str(tax_level3.tax_dpp_max-tax_level2.tax_dpp_max))
                elif total_bruto_50 > tax_level2.tax_dpp_max and total_bruto_50 <= tax_level3.tax_dpp_max:
                    self.lapis = '3'
                    pph_lapis_3 = ((total_bruto_50 - tax_level2.tax_dpp_max) * (tax_level3.tax_rate if self.is_npwp else tax_level3.tax_rate2) / 100.0)
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 3 Bruto 50%: ' + str(total_bruto_50 - tax_level2.tax_dpp_max))
                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 3: ' + str(pph_lapis_3))

                # hitung pph lapis 4
                if total_bruto_50 > tax_level4.tax_dpp_max:
                    pph_lapis_4 = (tax_level4.tax_dpp_max - tax_level3.tax_dpp_max) * (tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2) / 100.0
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 4 Bruto 50%: ' + str(tax_level4.tax_dpp_max - tax_level3.tax_dpp_max))
                elif total_bruto_50 > tax_level3.tax_dpp_max and total_bruto_50 <= tax_level4.tax_dpp_max:
                    self.lapis = '4'
                    pph_lapis_4 = ((total_bruto_50 - tax_level3.tax_dpp_max) * (tax_level4.tax_rate if self.is_npwp else tax_level4.tax_rate2) / 100.0)
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 4 Bruto 50%: ' + str(total_bruto_50 - tax_level3.tax_dpp_max))

                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 4: ' + str(pph_lapis_4))

                # hitung pph lapis 5
                if total_bruto_50 > tax_level4.tax_dpp_max:
                    self.lapis = '5'
                    pph_lapis_5 = ((total_bruto_50 - tax_level4.tax_dpp_max) * (tax_level5.tax_rate if self.is_npwp else tax_level5.tax_rate2) / 100.0)
                    # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 5 Bruto 50%: ' + (total_bruto_50 - tax_level4.tax_dpp_max))
                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Lapis 5: ' + str(pph_lapis_5))
                # open('/opt/odoo16/logs/log_fee_doctor.log','a+').write('\n PPH Previous: ' + str(previous_pph21))

                # 2021.08.04 perhitungan PPH 21 u/ Internal Doctor
                # hitung PPh bulan ini adalah total PPH dikurangi PPH yg sudah dibayar bulan sebelumnya
                if self.is_dental is not True and self.is_external is not True:
                    self.pph_21 = (pph_lapis_1 + pph_lapis_2 + pph_lapis_3 + pph_lapis_4 + pph_lapis_5) - previous_pph21
                # 2021.08.04 perhitungan PPH 23 % u/ Dental
                else:
                    # 2% untuk WP yg memiliki NPWP, 4% untuk yg tidak ada NPWP
                    self.pph_21 = (self.bruto *  ((tax_pph23.tax_rate if self.is_npwp else tax_pph23.tax_rate2)) / 100.0)

                # jika total fee grossup diatas nol
                if self.total > 0:
                    self.total_nett = self.total - self.pph_21
                    self.thp = self.total - self.pph_21 + self.deduction
            
        else:
            raise exceptions.ValidationError('Doctor rate ' + str(self.doctor_id.name) + ' not found!, please input doctor rate first.')


