    # @api.multi
    def confirm(self):
        for record in self:
            record.state = 'confirmed'
            for tl in record.transaction_line_ids:
                tl.state = 'confirmed'


    # @api.multi
    def unpost(self):
        for record in self:
            if record.state == 'posted':
                record.state = 'confirmed'
                if record.journal_id:
                    move = record.journal_id
                    move.button_cancel()
                    move.unlink()


    # @api.multi
    def cancel(self):
        for record in self:
            record.state = 'cancel'
            for tl in record.transaction_line_ids:
                tl.state = 'cancel'


    # @api.multi
    def set_draft(self):
        for record in self:
            record.state = 'draft'
            for tl in record.transaction_line_ids:
                tl.state = 'draft'


    # @api.multi
    def unconfirm(self):
        for record in self:
            record.state = 'draft'
            for tl in record.transaction_line_ids:
                tl.state = 'draft'

