            detail['bed_type'] = t['bed_type'] or ''

            if record.company_id.sync_type == '2' and (t['bpjs_remark'] or t['service_name'] in ['Consultation','Surgeon Fee','Anesthetist Fee','Asst Surgeon Fee']):
                service_item = t['service_name'] or ''
            else:
                service_item = t['service_item_name'] or ''
            
            detail['service_item'] = service_item
            detail['net_amount'] = float(t['total']) or 0.0000
            detail['net_amount_new'] = float(t['total_new']) or 0.0000
            detail['fee'] = float(t['rate']) or 0.0000
            detail['rate_percent'] = float(t['rate_percent']) or 0.0000
