        query = """
            INSERT INTO doctor_payout_line (
                line_id, account_analytic_id, bill_date, currency_id, billno, 
                company_id, department_id, discount, discount_rate, 
                item_specialisation, special_group, special_group2, patient_group, 
                service_group, lob_los, location_id, name, parent_analytic_id, 
                partner_id, patient_type, payer, payer_code, payer_name, 
                payer_type, perform_doc_id, prescribe_doc_id, 
                price_unit, price_subtotal, price_discount, price_total, 
                primary_doc_id, product_id, product_uom, product_uom_qty, patient_regcode,
                order_date, order_id, service_categ_id, tglproses, type_line, 
                bed_type, is_package, package_id, package_name, billing_id,
                order_no, order_item_no, reference_no, admit_date, 
                admission_no, order_type, create_date, write_date )
            SELECT 
                a.id, a.account_analytic_id, 
                coalesce(a.bill_date, sob.confirmation_date) bill_date, 
                a.currency_id, coalesce(a.billno, sob.billno) billno, 
                a.company_id, a.department_id, a.discount, 
                (case when coalesce(a.price_subtotal,0) = 0 then 0 
                    else (coalesce(ds.price_discount, 0)/a.price_subtotal * 100.0 * -1) 
                end) discount_rate,
                a.item_specialisation, a.special_group, a.special_group2, 
                (CASE WHEN a.department_id ilike '%%MCU%%' OR a.department_id ilike '%%PCRR%%'
                    THEN 'MCU' ELSE a.patient_group END) patient_group, 
                a.service_group, a.lob_los, a.location_id, a.name, a.parent_analytic_id, 
                a.partner_id, so.patient_type, a.payer, a.payer_code, a.payer_name, 
                a.payer_type, a.perform_doc_id, a.prescribe_doc_id, 
                a.price_unit, a.price_subtotal, ds.price_discount, 
                (a.price_total + coalesce(ds.price_discount, 0)) price_total, 
                a.primary_doc_id, a.product_id, a.product_uom, a.product_uom_qty, 
                a.registration_code as patient_regcode,
                (a.order_date - interval '7 hours') order_date, 
                a.order_id, a.service_categ_id, a.tglproses, a.type_line, 
                a.bed_type, a.is_package, a.package_id, a.package_name, 
                a.billing_id, a.order_no, a.order_item_no, '{reference_no}' reference_no, 
                a.admit_date, so.name admission_no, a.order_type,
                CURRENT_TIMESTAMP create_date,
                CURRENT_TIMESTAMP write_date
            FROM sale_order_line a
            INNER JOIN sale_order so ON so.id = a.order_id 
            INNER JOIN product_category b ON a.service_categ_id=b.id AND a.sync_type=b.sync_type
            INNER JOIN product_product pp ON pp.id = a.product_id
            INNER JOIN product_template pt ON pt.id = pp.product_tmpl_id
            LEFT JOIN sale_order_bill sob ON sob.id = a.billing_id
            LEFT JOIN LATERAL (
                SELECT sum(sol.price_total) price_discount
                FROM sale_order_line sol 
                WHERE sol.tglproses = a.tglproses 
                    AND sol.order_id = a.order_id 
                    AND sol.billno = a.billno
                    AND sol.order_no = a.order_no
                    AND coalesce(sol.order_item_no,'[NONE]') = coalesce(a.order_item_no,'[NONE]')
                    AND sol.service_categ_id = a.service_categ_id 
                    AND sol.product_id = a.product_id
                    AND sol.is_takeout is not True 
                    AND sol.type_line = 'DISCOUNT'
            ) ds ON 1=1
            WHERE a.tglproses >= '{start_date}'
                AND a.tglproses <= '{end_date}' 
                AND a.company_id = '{company_id}'
                AND a.type_line in ('BILL','BILLING')
                AND COALESCE(sob.state, 'done') not in('cancel') --billing belum cancel
                AND b.name not in('Drugs','Pharmacy','Consumable','Consumables','Bed Rentals','Administrative Charges', 'Food & Beverages')
                AND (a.department_id not in ('Laboratorium','LABORATORIUM','LABORATORY') OR a.sync_type = '8' )
                AND pt.name not in ('DISKON','ADMINISTRASI','Cetak Foto dengan Film', 'PEMBULATAN','Akomodasi') -- Request MHKN
                {exclude_bpjs} -- Request MHSB
                AND a.is_takeout is not True
                AND a.order_id in(
                    SELECT t.order_id
                    FROM sale_order_line t
                    INNER JOIN sale_order t2 ON t2.id = t.order_id
                    WHERE t.tglproses >= '{start_date}' 
                        and t.tglproses <= '{end_date}' 
                        and t.company_id = '{company_id}' 
                        and t.type_line in ('BILL','BILLING')
                        and coalesce(t.billno,'') like '%{billno}%'
                        and coalesce(t2.name,'') like '%{admission_no}%'
                    GROUP BY t.order_id
                )
                AND NOT EXISTS (
                    SELECT 1 FROM doctor_payout_line t 
                    WHERE t.line_id=a.id LIMIT 1
                )
                /* 
                AND NOT EXISTS (
                    SELECT 1 
                    FROM doctor_payout_line t 
                    WHERE t.order_id = a.order_id
                    AND t.service_categ_id = a.service_categ_id
                    AND t.product_id = a.product_id 
                    AND coalesce(t.order_no,'[NULL]') = coalesce(a.order_no,'[NULL]')
                    LIMIT 1
                ) */
            """.format(
                reference_no=reference_no, 
                start_date=start_date, 
                end_date=end_date, 
                company_id=company_id, 
                exclude_bpjs=exclude_bpjs, 
                billno=billno, 
                admission_no=admission_no)
        open('/opt/odoo16/logs/doctor_fee.log', 'a+').write('\n\n'+str(query))
        self.env.cr.execute(query)


        # 2021.08.04 semua pendaftaran pasien yg contain department/area MCU/PCRR dianggap paket rate fee 100%
        query = """
            UPDATE doctor_payout_line AS dpl SET patient_group='MCU'
            WHERE dpl.company_id={company_id}
            AND EXISTS(
                SELECT 1 FROM sale_order_line t
                WHERE t.order_id=dpl.order_id 
                AND (t.department_id ilike '%%MCU%%'
                 OR t.department_id ilike '%%PCRR%%'))
        """.format(company_id=company_id, reference_no=reference_no)
        open('/opt/odoo16/logs/doctor_fee.log', 'a+').write('\n\n'+str(query))
        self.env.cr.execute(query)



        # 2024.01.31 - update order_item_no untuk pembeda jika ada service cateegory yg sama dalam satu order_no
        query = """
            update doctor_payout_line as t set 
                order_item_no=cast(a.order_item_id as varchar) 
            from (
                select 
                    (row_number() over (partition by order_no, service_categ_id, product_id order by id asc)) order_item_id, 
                    a.order_no, a.admission_no, a.order_item_no, a.order_date, a.service_categ_id, a.product_id, a.id 
                from doctor_payout_line a 
                where a.order_no in (
                    select dpl.order_no --, dpl.service_categ_id, dpl.product_id, count(*) 
                    from doctor_payout_line AS dpl 
                    where dpl.company_id={company_id}
                        and dpl.reference_no = '{reference_no}'
                    group by dpl.order_no, dpl.service_categ_id, dpl.product_id  
                    having count(*) > 1 
                ) 
                and a.company_id=1
                and a.reference_no='{reference_no}'
                order by a.order_no asc 
            ) a 
            where t.company_id=1
                and t.reference_no='{reference_no}' 
                and t.id=a.id 
        """.format(company_id=company_id, reference_no=reference_no)
        open('/opt/odoo16/logs/doctor_fee.log', 'a+').write('\n\n'+str(query))
        self.env.cr.execute(query)

