class DoctorFeeOthersImportWizard(models.TransientModel):
    _name = "doctor.fee.others.import.wizard"

    @api.model
    def _get_company(self):
        return self.env.company.id

    def _get_doctor_fee(self):
        return self.env.context.get('doctor_fee_id')
    
    doctor_fee_id = fields.Many2one('doctor.fee', default=_get_doctor_fee, string="Fee Doctor (Internal)")
    company_id = fields.Many2one('res.company',string="Company",required=True,default=_get_company)
    upload_file = fields.Binary(string="Upload File")
    filename = fields.Char(string="filename")
    attachment_ids = fields.Many2many(
        comodel_name='ir.attachment',
        string='Attachments',
    )
    uploaded = fields.Boolean()

    def upload(self):
        if not self.attachment_ids:
            #  raise UserError(
            #     "Attachment Kosong, Harap Diisi Terlebih Dahulu")
            raise UserError(_("Attachment Kosong, Harap Diisi Terlebih Dahulu"))
        if not self.company_id:
            #  raise UserError(
            #     "Company Kosong, Harap Diisi Terlebih Dahulu")
            raise UserError(_("Attachment Kosong, Harap Diisi Terlebih Dahulu"))
        salah = ""
        baris_salah = ""
        if self.uploaded:
            # raise UserError(
            #     "Data has been processed. \
            #     Please close and click the same menu to upload again.")
            raise UserError(_("Data has been processed...!!! Please close and click the same menu to upload again."))
        for attachment in self.attachment_ids:
            wb = open_workbook(
                file_contents=base64.decodebytes(attachment.datas))
            if not wb:
                raise UserError("Please Attach xlsx")
            values = []
            for s in wb.sheets():
                for row in range(s.nrows):
                    col_value = []
                    for col in range(s.ncols):
                        value = (s.cell(row, col).value)
                        col_value.append(value)
                    values.append(col_value)

            line = 1
            baris = 1
            
        # open('/opt/odoo16/logs/dump.log','a+').write('\n' + str(values))
        
        for val in values:
            if line == 1:
                line += 1
                continue
            baris += 1

            # if not val[0] or not val[1] or not val[2] or not val[3] or not val[4]:
            if not val[0] and not val[1] and not val[2] and not val[3] and not val[4]:
                continue
                # raise UserError(_("Terdapat Data yang kosong pada baris " + str(baris)))
                # raise UserError("Terdapat Data yang kosong pada baris " + str(baris))
            if not val[5]:
                val[5] = 0
                
            type = val[0]
            
            bill = val[1]
            bill_id = self.env['sale.order.bill'].search([('billno', '=', bill), ('company_id','=', self.company_id.id)], limit=1).id or None
            
            analytic = val[2]
            analytic_id = self.env['account.analytic.account'].search([('name', '=', analytic), ('company_id','=', self.company_id.id)], limit=1).id or None
            
            item = val[3]
            description = val[4]
            amount = val[5]
            
            # open('/opt/odoo16/logs/dump.log','a+').write('\n' + str(type))
            # open('/opt/odoo16/logs/dump.log','a+').write('\n' + str(bill_id))
            # open('/opt/odoo16/logs/dump.log','a+').write('\n' + str(analytic_id))
            # open('/opt/odoo16/logs/dump.log','a+').write('\n' + str(item))
            # open('/opt/odoo16/logs/dump.log','a+').write('\n' + str(description))
            # open('/opt/odoo16/logs/dump.log','a+').write('\n' + str(amount))
            
            self.env['other.transaction'].create({
                'other_type' : type,
                'doctor_fee_id' : self.doctor_fee_id.id,
                'analytic_account_id' : analytic_id,
                'bill_id' : bill_id,
                'item' : item,
                'description' : description,
                'amount' : amount
            })
            


