                open('/opt/odoo16/logs/doctor_fee_bulk_update.log', 'a+').write('\n'+str(query))

                self.sudo().env.cr.execute(query)
                open('/opt/odoo16/logs/doctor_fee_bulk_update.log', 'a+').write(str('\nDone'))

