# 20210701 - Bulk Update Doctor Payout Line
# Request Titis u/ Koreksi Payout MCU 
class PayoutBulkUpdateWizard(models.TransientModel):
    _name = 'payout.bulk.update.wizard'

    @api.model
    def _get_company(self):
        return self.env.company.id
    
    company_id = fields.Many2one('res.company', string='Company', default=_get_company)
    column_name = fields.Selection([('price_total', 'Total Revenue'),('account_analytic_id', 'Analytic Doctor'),('service_categ_id', 'Service Category')], string='Column Name', default='price_total')
    analytic_account = fields.Many2one('account.analytic.account', string="Doctor Name")
    service_categ_id = fields.Many2one('product.category', string="Service Category")
    price_total = fields.Float(string="Bill Amount", default=0)
    payout_line_ids = fields.Many2many('doctor.payout.line', relation='doctor_payout_line_update', string="Doctor Payout Line", required=True, store=True)


    # @api.multi
    def bulk_update(self):
        report_id = self.id 
        column_name = self.column_name
        company_id = self.company_id.id 
        
        if column_name in ['account_analytic_id']:
            column_value = self.analytic_account.id
        elif column_name in ['price_total']:
            column_value = self.price_total 
        elif column_name in ['service_categ_id']:
            column_value = self.service_categ_id.id 

        open('/opt/odoo16/logs/payout_bulk_update.log', 'a+').write(str('\nStart update doctor.payout.line:'))
        query = """
            UPDATE doctor_payout_line AS a set 
                {column_name} = {column_value},
                write_date = CURRENT_TIMESTAMP,
                write_uid = {user_id}
            WHERE a.id IN (
                SELECT t.doctor_payout_line_id
                FROM doctor_payout_line_update t
                WHERE t.payout_bulk_update_wizard_id = {report_id}
            ) AND a.company_id = {company_id}
        """.format(
            report_id=report_id, 
            company_id=company_id, 
            column_name=column_name, 
            column_value=column_value,
            user_id=self.env.user.id)
        open('/opt/odoo16/logs/payout_bulk_update.log', 'a+').write('\n'+str(query))

        self.sudo().env.cr.execute(query)
        open('/opt/odoo16/logs/payout_bulk_update.log', 'a+').write(str('\nDone'))
        print("Successfully to update doctor.payout.line")
        #raise exceptions.UserError('Successfully to update sale.order.line')





