    # @api.multi
    def compute_fee(self):
        self._compute_fee_line()

    # @api.multi
    def _compute_fee_line(self):
        for record in self:
            if record.state == 'draft':
                record.rate = 0
                record.rate_percent = 0
                # update doctor fee header
                doctor_fee = self.env['doctor.fee'].search([
                    ('company_id', '=', record.company_id.id),
                    ('year', '=', record.year), ('month', '=', record.month),
                    ('doctor_id', '=', record.odoo_doctor_id.id)
                ])
                if not doctor_fee:
                    raise exceptions.ValidationError("Fee Header untuk dokter ini untuk periode yang anda pilih belum ada.")

                # setting doctor fee head
                record.doctor_fee_id = doctor_fee.id

                doctor_rate = self.env['doctor.rate'].search([
                    ('company_id', '=', record.company_id.id),
                    ('doctor_id', '=', record.odoo_doctor_id.id)
                ])
                if not doctor_rate:
                    raise exceptions.ValidationError("Master Rate untuk dokter ini belum ada.")

                for dc in doctor_rate:
                    drl_1 = self.env['doctor.rate.line'].search(
                        [('doctor_rate_id', '=', dc.id),
                         ('service_id', '=', record.odoo_service_id.id),
                         ('product_id', '=', record.odoo_service_item_id.id),
                         ('patient_type', '=', record.patient_type),
                         ('type_rate', '=', record.rate_remark)],
                        limit=1)
                    drl_2 = self.env['doctor.rate.line'].search(
                        [('doctor_rate_id', '=', dc.id),
                         ('service_id', '=', record.odoo_service_id.id),
                         ('product_id', '=', record.odoo_service_item_id.id),
                         ('patient_type', '=', False),
                         ('type_rate', '=', record.rate_remark)],
                        limit=1)
                    drl_3 = self.env['doctor.rate.line'].search(
                        [('doctor_rate_id', '=', dc.id),
                         ('service_id', '=', record.odoo_service_id.id),
                         ('product_id', '=', False),
                         ('patient_type', '=', record.patient_type),
                         ('type_rate', '=', record.rate_remark)],
                        limit=1)
                    drl_4 = self.env['doctor.rate.line'].search(
                        [('doctor_rate_id', '=', dc.id),
                         ('service_id', '=', record.odoo_service_id.id),
                         ('product_id', '=', False),
                         ('patient_type', '=', False),
                         ('type_rate', '=', record.rate_remark)],
                        limit=1)

                #case POT share
                if doctor_rate.is_pot_gp is True and record.patient_type in (
                        '2', '3') and record.service_name in (
                            'Consultation', 'OP/IP Procedure'
                        ) and record.service_item_name not in (
                            'ECG', 'PUNCTION ASCITES ABDOMEN (INTERNA)',
                            'PUNCTION ASCITES ABDOMEN (INTERNA)',
                            'HECTING FACE REGION MINOR (GENERAL SURGEON)',
                            'VENTILATOR SETTING',
                            'SET VENTILATOR (PAIN CLINIC)', 'TREADMILL'):
                    record.is_pot_gp = True
                    #rate type 1
                    if drl_1:
                        if drl_1.rate_value > 0:
                            record.rate_percent = drl_1.rate_value
                            if record.total > 0:
                                record.rate = 0
                                record.rate_pot = drl_1.rate_value
                            else:
                                record.rate = 0
                                record.rate_pot = 0
                        else:
                            if record.patient_group == 'MCU':
                                record.rate_percent = 100
                                record.rate = 0
                                record.rate_pot = (record.total * 100 / 100)
                            else:
                                record.rate_percent = drl_1.rate
                                record.rate = 0
                                record.rate_pot = (record.total * drl_1.rate /100)
                    #rate type 2
                    elif drl_2:
                        if drl_2.rate_value > 0:
                            record.rate_percent = drl_2.rate_value
