                odoo_service_item_id, service_item_id, service_item_name, bed_type, order_id, arcus_order_id,
                order_item_id, arcus_order_item_id, order_no, order_date, odoo_doctor_id, doctor_id, doctor_code, 
                doctor_name, odoo_primary_id, primary_id, primary_code, primary_name, prescribe_id, prescribe_code, 
                prescribe_name, perform_id, perform_code, perform_name, total, rate, rate_percent, rate_remark, 
                state, doctor_mcu_line_id, order_date_start, order_date_end,
