class OtherTransaction(models.Model):
    _name = 'other.transaction'

    sync_type = sync.type
    sync_consol_id_unit = sync.consol_id_unit
    sync_consol_id_main = sync.consol_id_main
    sync_consol_date = sync.consol_date

    item = fields.Char(string="Item")
    description = fields.Char(string="Description")
    amount = fields.Float(string="Amount")
    other_type = fields.Selection([('OTHER', 'OTHERS'), ('BPJS', 'BPJS'),('REGULER', 'REGULER')],string='Type',required=True)
    partner_id = fields.Many2one('res.partner', related='bill_id.payer_id', string="Insurance", store=True)
    patient_id = fields.Many2one('res.partner', related='bill_id.partner_id', string="Patient Name")
    doctor_fee_id = fields.Many2one('doctor.fee')
    year = fields.Integer(string="Year Period", related='doctor_fee_id.year')
    month = fields.Selection(string="Year Period", related='doctor_fee_id.month')
    state = fields.Selection(string="Status", related='doctor_fee_id.state')
    credit_gf = fields.Boolean(string="Credit GF")
    analytic_account_id = fields.Many2one('account.analytic.account', string="Analytic Account")
    bill_id = fields.Many2one('sale.order.bill', string="Billing No")
    bill_date = fields.Date(string="Billing Date", related='bill_id.bill_date', store=False)
    patient_type = fields.Selection(string="Patient Type", related='bill_id.patient_type')

    @api.model
    def create(self, vals):
        result = super(OtherTransaction, self).create(vals)
        if result.doctor_fee_id.company_id.cost_center_active:
            if len(str(result.doctor_fee_id.month)) == 1:
                month = "0"+str(result.doctor_fee_id.month)
            if len(str(result.doctor_fee_id.month)) == 2:
                month = str(result.doctor_fee_id.month)
            df_date_str = str(result.doctor_fee_id.year) + "-" + month + "-01"
            if not df_date_str or not result.doctor_fee_id.company_id.cost_center_date:
                raise UserError(_("Tanggal tidak boleh kosong."))
            if (result.doctor_fee_id.company_id.cost_center_date <= df_date_str) and not result.analytic_account_id:
                raise UserError(_("Analytic Account untuk Other harus diisi."))
            
        return result



class DeductionTransaction(models.Model):
    _name = 'deduction.transaction'

    sync_type = sync.type
    sync_consol_id_unit = sync.consol_id_unit
