    sync_consol_date = sync.consol_date

    item = fields.Char(string="Item")
    description = fields.Char(string="Description")
    amount = fields.Float(string="Amount")
    doctor_fee_id = fields.Many2one('doctor.fee')
    analytic_account_id = fields.Many2one('account.analytic.account', string="Analytic Account")

    @api.model
    def create(self, vals):
        result = super(DeductionTransaction, self).create(vals)
        if result.doctor_fee_id.company_id.cost_center_active:
            if len(str(result.doctor_fee_id.month)) == 1:
                month = "0"+str(result.doctor_fee_id.month)
            if len(str(result.doctor_fee_id.month)) == 2:
                month = str(result.doctor_fee_id.month)
            df_date_str = str(result.doctor_fee_id.year) + "-" + month + "-01"
            if not df_date_str or not result.doctor_fee_id.company_id.cost_center_date:
                raise UserError(_("Tanggal tidak boleh kosong."))
            if (result.doctor_fee_id.company_id.cost_center_date <= df_date_str) and not result.analytic_account_id:
                raise UserError(_("Analytic Account untuk Deduction harus diisi."))
            
        return result



