        if not self.company_id:
             raise UserError(
                "Company Kosong, Harap Diisi Terlebih Dahulu")
        salah = ""
        baris_salah = ""
        if self.uploaded:
            raise UserError(
                "Data has been processed. \
                Please close and click the same menu to upload again.")
        for attachment in self.attachment_ids:
            wb = open_workbook(
                file_contents=base64.decodebytes(attachment.datas))
            if not wb:
                raise UserError("Please Attach xlsx")
            values = []

            i = 0
            for s in wb.sheets():
                # hanya sheet pertama yang diambil
                if i > 0:
                    continue
                i = i + 1

                for row in range(s.nrows):
                    col_value = []
                    for col in range(s.ncols):
                        value = (s.cell(row, col).value)
                        col_value.append(value)
                    values.append(col_value)



            line = 1
            baris = 1
            for val in values:
                if line == 1:
                    line += 1
                    continue
                baris += 1
                
                # skip jika billno memang sudah kosong tidak perlu diproses 
                if not val[0] and not val[1]:
                    continue
                if str(val[0]).strip().lower() == 'bill date' or str(val[1]).strip().lower() == 'bill no':
                    continue

                if not val[3] or not val[4] or not val[5] or not val[6] or not val[16]:
                    raise UserError("Terdapat Data yang kosong pada baris " + str(baris))
                if not val[2]:
                    val[2] = None
                if not val[7]:
                    val[7] = None
                if not val[8]:
                    val[8] = None
                if not val[9]:
                    val[9] = None
                if not val[10]:
                    val[10] = 0
                if not val[11]:
                    val[11] = 0
                if not val[12]:
                    val[12] = 0
                if not val[13]:
                    val[13] = 0
                if not val[14]:
                    val[14] = 0
                if not val[15]:
                    val[15] = 0
                if not val[17]:
                    val[17] = 0
        
                # company = val[0]
                # company_id = self.env['res.company'].search([('name','=', company)], limit=1)
                #analytic_code = val[1]
                #analytic_code_id = self.env['account.analytic.account'].search([('code', '=', val[1]), ('company_id','=', 8)],limit=1)
                #account_debit = val[2]
