    def _year(orm):
        result = []
        year = 2020
        now = tools.datetime.now().year
        for loop in range(now - year):
            value = str(year + loop + 1)
            result += [(value, value)]
        # for loop in range(10):
        #     value = str(now + loop)
        #     result += [(value, value)]
        return result

