        for attachment in self.attachment_ids:
            wb = open_workbook(file_contents=base64.decodebytes(attachment.datas))
            if not wb:
                raise UserError("Please Attach xlsx")
            values = []

            i = 0
            for s in wb.sheets():
                # hanya sheet pertama yang diambil
                if i > 0:
                    continue
                i = i + 1

                for row in range(s.nrows):
                    col_value = []
                    for col in range(s.ncols):
                        value = (s.cell(row, col).value)
                        col_value.append(value)
                    values.append(col_value)



            line = 1
            baris = 1
            total_pot = 0

            for val in values:
                if line == 1:
                    line += 1
                    continue
                baris += 1
                

                # skip jika billno memang sudah kosong tidak perlu diproses 
                if not val[0] and not val[1]:
                    continue
                if str(val[0]).strip().lower() == 'year' or str(val[1]).strip().lower() == 'month':
                    continue

                if not val[3]:
                    raise UserError("Terdapat Kode Dokter yang kosong pada baris " + str(baris))
                
                str_year = val[0]
                str_month = val[1]
                str_code = val[2]
                str_point = 0

                if val[4]:
                    str_point = int(val[4])
                if val[5]:
                    str_point = int(val[5])
                if val[6]:
                    str_point = int(val[6])
                if val[7]:
                    str_point = int(val[7])
                if val[8]:
                    str_point = int(val[8])
                
                
        
                query_doctor = """
                select
                df.id
                from
                doctor_fee df 
                left join account_analytic_account aac on aac.id = df.doctor_id
                where
                df.company_id = '{company_id}'
                and df.year='{year}'
                and df.month='{month}'
                and df.state ='{state}'
                and trim(aac.code) = '{str_code}'
                limit 1
                 """.format(
                company_id = self.company_id.id,
                year = self.year,
                month = self.month,
                state = 'draft',
                str_code = (str(str_code)).replace('.0',''),
                )
