    month = fields.Selection([('1', 'January'), ('2', 'February'), ('3', 'March'),('4', 'April'), ('5', 'May'), ('6', 'June'),('7', 'July'), ('8', 'August'), ('9', 'September'),('10', 'October'), ('11', 'November'),('12', 'December')],string='Month Period',required=True)
    doctor_fee_tnc_id = fields.Many2one('doctor.fee',string="Doctor TNC.",required=True)




    # @api.multi
    def print_tnc(self):
        action = {}
        action['type'] = 'ir.actions.act_url'
