class DoctorRateBulkUpdateWizard(models.TransientModel):
    _name = 'doctor.rate.bulk.update.wizard'

    def _get_company(self):
        return self.env.company.id
    
    @api.model
    def _get_user_id(self):
        return self.env.user.id

    company_id = fields.Many2one('res.company', string="Company", required=True, default=_get_company)
    column_name = fields.Selection([('service_id', 'Service'), ('type_rate', 'Type Rate'), ('rate', 'Rate Percentage'), ('rate_value', 'Rate Value'), ('payer_id', 'Payer'), ('patient_type', 'Patient Type'), ('take_out', 'Take Out'), 
                                    ('bed_type', 'Bed Type'), ('bed_type_id', 'BedType ID'), ('is_hospital_sharing', 'Hospital Sharing?'), ('hospital_sharing_amount', 'Hospital Sharing Amount'), ('package_id', 'Package')], string='Column Name', default='service_id')
    
    service_id = fields.Many2one('product.category', string="Service")
    product_id = fields.Many2one('product.product', string="Service Item")
    type_rate = fields.Selection([('doctor', 'Doctor'), ('primary', 'Primary'),('perform', 'Perform'),('prescribe', 'Prescribe'),('referal', 'Referal'),('verified', 'Verified')],string="Type Rate")
    rate = fields.Float(string="Rate Percentage")
    rate_value = fields.Float(string="Rate Value")
    payer_id = fields.Many2one('res.partner', string="Payer")
    patient_type = fields.Selection([('1', 'OP'), ('2', 'IP'),('3', 'Emergency'), ('4', 'Daycare'),('5', 'MCU'), ('6', 'Pharmacy'),('0', 'Both')],string='Patient Type')
    take_out = fields.Boolean(string="Take Out")

    bed_type = fields.Char(string="Bed Type")
    bed_type_id = fields.Many2one('hospital.bed.type',string='BedType ID',index=True)
    is_hospital_sharing = fields.Boolean(string="Hospital Sharing?")
    hospital_sharing_amount = fields.Float(string="Hospital Sharing Amount")
    package_id = fields.Many2one('product.product', string="Package")
    user_id = fields.Many2one('res.users', string="Responsible", default=_get_user_id)
    doctor_rate_line_ids = fields.Many2many('doctor.rate.line', string="Doctor Rate Line")
    
    
    # @api.multi
    def delete_rate(self):
        record = self.sudo()
        if record.doctor_rate_line_ids:
            for line in record.doctor_rate_line_ids:
                line.unlink()
            
    # @api.multi
    def update_rate(self):
        record = self.sudo()
        if record.doctor_rate_line_ids:
            for line in record.doctor_rate_line_ids:
                if record.column_name == "service_id":
                    line.service_id = record.service_id.id
                    line.product_id = record.product_id.id
                elif record.column_name == "package_id":
                    line.package_id = record.package_id.id
                elif record.column_name == "take_out":
                    line.take_out = record.take_out
                elif record.column_name == "patient_type":
                    line.patient_type = record.patient_type
                elif record.column_name == "rate":
                    line.rate = record.rate
                elif record.column_name == "type_rate":
                    line.type_rate = record.type_rate
                elif record.column_name == "rate_value":
                    line.rate_value = record.rate_value or None
                elif record.column_name == "bed_type":
                    line.bed_type = record.bed_type
                elif record.column_name == "bed_type_id":
                    line.bed_type_id = record.bed_type_id.id
                elif record.column_name == "is_hospital_sharing":
                    line.is_hospital_sharing = record.is_hospital_sharing
                elif record.column_name == "hospital_sharing_amount":
                    line.hospital_sharing_amount = record.hospital_sharing_amount
                elif record.column_name == "payer_id":
                    line.payer_id = record.payer_id.id
            

class DoctorFeeSendEmailWizard(models.TransientModel):
    _name = 'doctor.fee.send.email.wizard'

    @api.model
    def _get_company(self):
        return self.env.company.id

    company_id = fields.Many2one('res.company',string="Company",required=True,default=_get_company)
    year = fields.Integer(string="Year Period", required=True)
    month = fields.Selection([('1', 'January'), ('2', 'February'), ('3', 'March'),('4', 'April'), ('5', 'May'), ('6', 'June'),('7', 'July'), ('8', 'August'), ('9', 'September'),('10', 'October'), ('11', 'November'),('12', 'December')],string='Month Period',required=True)
    actual_date = fields.Date(string="Actual Date", required=True)
    payment_type = fields.Selection([('cash', 'Cash'), ('transfer', 'Bank Transfer')],string='Payment Type', required=True)
    doctor_fee_ids = fields.Many2many('doctor.fee', relation='doctor_fee_email_rel', string="Doctor Fee (Odoo)", store=True)

    @api.model
    def get_view(self,view_id=None, view_type='form', **options):
        res = super(DoctorFeeSendEmailWizard,self).get_view(view_id=view_id,view_type=view_type, **options)  
        if view_type == 'form':
            res['arch'] = """
                <form string="Doctor Fee Send Email">
                    <group>
                        <group>
                            <field name="company_id" />
                            <field name="year" />
                            <field name="month" />
                        </group>
                        <group>
                            <field name="actual_date" />
                            <field name="payment_type" />
                        </group>
                    </group>
                    <group> 
                        <field name="doctor_fee_ids" domain="[('company_id', '=', company_id),('email_send', '=', False),('year', '=', year),('month', '=', month), ('state', 'in', ['confirmed','posted'])]">
                            <tree>
                                <field name="year" string="Year"/>
                                <field name="month" string="Month"/>
                                <field name="doctor_id"/>
                                <field name="state"/>
                                <field name="thp" string="THP" sum="Total" widget="monetary"/>
                            </tree>
                        </field>
                    </group> 
                    <footer>
                        <button name="send_email_bulk" string="Send Email" type="object" class="oe_highlight"/>
                    </footer>
                </form>
            """
        from lxml import etree
        doc = etree.XML(res['arch'])
        View = self.env['ir.ui.view'].sudo()
        res['arch'], res['fields'] = View.postprocess_and_fields(doc, self._name, validate=True)
        return res


    # @api.one
    def send_email_bulk(self):
        if self.doctor_fee_ids:
            # get email address
            query = """
                select DISTINCT df.doctor_id, rt.email from doctor_fee df 
                    inner join lateral (select rt.doctor_id, rt.email from doctor_rate rt where rt.doctor_id=df.doctor_id) AS rt on 1=1
            """
            self.env.cr.execute(query)
            result = self.env.cr.dictfetchall()

            doctor_fee = self.env['doctor.fee']
            for line in self.doctor_fee_ids:
                if line.company_id.company_code == 'MHBG':
                    pdf_base64 = doctor_fee._get_file_src_mhbg(line.id, ext='pdf')
                elif line.company_id.company_code == 'MHTG':
                    pdf_base64 = doctor_fee._get_file_src_mhtg(line.id, ext='pdf')
                elif line.company_id.company_code == 'MHJS':
                    pdf_base64 = doctor_fee._get_file_src_arcus(line.id, ext='pdf')
                else:
                    pdf_base64 = doctor_fee._get_file_src(line.id, ext='pdf')

                if isinstance(pdf_base64, list) and len(pdf_base64) > 0:
                    pdf_base64 = pdf_base64[0]

                if not pdf_base64:
                    raise UserError("PDF tidak ada")

                header_template = line.env['ir.config_parameter'].sudo().get_param('doctor_fee.email_header')
                body_template = line.env['ir.config_parameter'].sudo().get_param('doctor_fee.email_body')

                values_header = {
                    'doctor_name': (line.doctor_id.name or '').upper(),
                    'month': datetime.datetime(2000, int(self.month), 1).strftime('%B') or '',
                    'year': line.year or ''
                }

                values_body = {
                    'doctor_name': line.doctor_id.name or '',
                    'month': datetime.datetime(2000, int(self.month), 1).strftime('%B') or '',
                    'year': line.year or '',
                    'nominal': "{:,.0f}".format(line.thp or 0).replace(',', '.'),
                    'actual_date': self.actual_date or '',
                    'company': line.company_id.name or '',
                    'payment_type': self.payment_type or ''
                }

                header_html = header_template.format(**values_header)
                body_html = body_template.format(**values_body)

                # Cek apakah attachment sudah ada
                existing_attachment = line.env['ir.attachment'].search([
                    ('name', '=', header_html + '.pdf'),
                    ('res_model', '=', line._name),
                    ('res_id', '=', line.id),
                ], limit=1)

                if existing_attachment:
                    # Update attachment yang sudah ada
                    existing_attachment.write({
                        'datas': pdf_base64,
                    })
                    attachment = existing_attachment
                else:
                    # Buat baru kalau belum ada
                    attachment = line.env['ir.attachment'].create({
                        'name': header_html + '.pdf',
                        'datas': header_html + '.pdf',
                        'type': 'binary',
                        'datas': pdf_base64,
                        'res_model': line._name,
                        'res_id': line.id,
                        'mimetype': 'application/pdf',
                    })

                # Ambil semua attachment yang sudah di-upload di line doctor.fee (logo.png, dll)
                existing_attachments = line.env['ir.attachment'].search([
                    ('res_model', '=', 'doctor.fee'),
                    ('res_id', '=', line.id),
                    ('id', '!=', attachment.id),  # exclude PDF yang baru dibuat
                ])

                # Gabungkan: PDF generated + attachment existing dari line
                all_attachment_ids = [(4, attachment.id)]
                for att in existing_attachments:
                    all_attachment_ids.append((4, att.id))
                
                email_to = next((data['email'] for data in result if data['doctor_id'] == line.doctor_id.id), False)
                line.email_send = True

                # raise exceptions.ValidationError(_(str(body_html)))
                # kirim email
                mail = line.env['mail.mail'].create({
                    'subject': header_html,
                    'body_html': body_html,
                    'email_to': email_to,
                    'email_from': 'odoo@mayapadahospital.com',
                    'attachment_ids': all_attachment_ids,
                })

                try:
                    mail.send()
                    line.email_send = True
                except Exception as e:
                    line.email_send = False
                    _logger.error("Gagal mengirim email: %s", str(e))
        else:
            raise exceptions.ValidationError(_('Dokter Harus Dipilih'))